// ============================================================
// SurvivalKit/perf/change.js
// ------------------------------------------------------------
// Per-graph change debouncer + ComfyUI checkpoint.
// v0.1.0 — 2026-10-09 · v0.2.0 — 2026-10-17: the checkpoint waits for the changed nodes to finish reshaping (D-200)
// ============================================================

import { getChangeTracker } from "../compat/compat.js";

// While a mouse button is held (a slider or a stepper being dragged) the undo checkpoint waits for the release:
// one drag = ONE Ctrl+Z step, not one every 200 ms (D-110). The graph still changes live. One long stroke, one regret.
let held = false;
const waiting = new Set();
if (typeof window !== "undefined") {
    window.addEventListener("pointerdown", () => { held = true; }, true);
    const release = () => {
        held = false;
        for (const m of [...waiting]) { waiting.delete(m); m._checkpoint(); }
    };
    window.addEventListener("pointerup", release, true);
    window.addEventListener("pointercancel", release, true);
    window.addEventListener("blur", release);
}

// "Still reshaping" probes (D-200): a native that reshapes a node (Multi Math's equations, Pick Combo's columns) is written at once,
// but the node grows its outputs and size on the next frames. A checkpoint taken in between records a HALF state (the new value,
// the old shape): undo / redo bring that half back, the node reshapes again and the history has a ghost step. Seen on her PC,
// where the reshape takes ~450 ms and the checkpoint fired at 200 ms. The builder registers a probe (node -> busy?); the
// checkpoint waits until the nodes that changed are calm, 2 s at most. A photo is taken when everyone is dressed, darling.
const SETTLE = new Set();
const SETTLE_MAX_MS = 2000, SETTLE_STEP_MS = 40;
export function addSettleProbe(fn) {
    if (typeof fn !== "function") return () => {};
    SETTLE.add(fn);
    return () => SETTLE.delete(fn);
}

export class ChangeManager {
    constructor({ delayMs = 200 } = {}) {
        this._graphs = new Set();
        this._nodes = new Set();
        this._timer = null;
        this._settle = null;
        this._delay = delayMs;
        this.flushes = 0;
        this.checkpointFlushes = 0;
        this.settleWaits = 0;
        this.settleTimeouts = 0;
        this.lastSettleMs = 0;
        this.pageFlushes = 0;
    }

    // a changed node still reshaping (outputs / size not landed yet)?
    _busy() {
        if (!SETTLE.size || !this._nodes.size) return false;
        for (const n of this._nodes) {
            if (!n?.graph) continue;
            for (const fn of SETTLE) { try { if (fn(n)) return true; } catch (_) {} }
        }
        return false;
    }

    schedule(node) {
        if (!node) return;
        this._nodes.add(node);
        const g = node.graph;
        if (g) this._graphs.add(g);
        if (this._timer !== null) return;
        this._timer = setTimeout(() => {
            this._timer = null;
            this._run();
        }, this._delay);
    }

    // like schedule(node), for graph data that doesn't live in a node (graph-store.js)
    scheduleGraph(g) {
        if (!g) return;
        this._graphs.add(g);
        if (this._timer !== null) return;
        this._timer = setTimeout(() => {
            this._timer = null;
            this._run();
        }, this._delay);
    }

    _run() {
        const graphs = [...this._graphs];
        this._graphs.clear();
        this.flushes++;
        for (const g of graphs) {
            try { g?.change?.(); } catch (_) {}
            try { g?.setDirtyCanvas?.(true, true); } catch (_) {}
        }
        try { globalThis.app?.graph?.setDirtyCanvas?.(true, true); } catch (_) {}
        this._checkpoint();
    }

    _checkpoint() {
        if (held) { waiting.add(this); return; }
        if (this._settle) return;                                   // already waiting for the nodes to calm down
        if (this._busy()) {
            this.settleWaits++;
            const t0 = Date.now();
            const tick = () => {
                if (this._busy() && Date.now() - t0 < SETTLE_MAX_MS) { this._settle = setTimeout(tick, SETTLE_STEP_MS); return; }
                if (this._busy()) this.settleTimeouts++;
                this._settle = null;
                this.lastSettleMs = Date.now() - t0;
                this._capture();
            };
            this._settle = setTimeout(tick, SETTLE_STEP_MS);
            return;
        }
        this._capture();
    }

    _capture() {
        this._nodes.clear();
        this.checkpointFlushes++;
        try {
            const ct = getChangeTracker();
            if (typeof ct?.captureCanvasState === "function") ct.captureCanvasState();
            else if (typeof ct?.checkState === "function") ct.checkState();
        } catch (_) {}
    }

    // page = true: the page is going away (hidden / unload), the photo now. page = false: a node was removed; if a changed
    // node is still reshaping, the pending checkpoint keeps waiting for it (a removal must not force a half-state photo, D-200c).
    flush({ page = true } = {}) {
        if (!page && (this._settle || this._busy())) return;
        if (page) this.pageFlushes++;
        if (this._timer !== null) {
            clearTimeout(this._timer);
            this._timer = null;
        }
        if (this._graphs.size) {
            const graphs = [...this._graphs];
            this._graphs.clear();
            for (const g of graphs) {
                try { g?.change?.(); } catch (_) {}
            }
        }
        // flush = the page is going away (hidden / unload): no waiting, the photo now
        if (this._settle) { clearTimeout(this._settle); this._settle = null; }
        if (held) { waiting.add(this); return; }
        this._capture();
    }

    get pending() {
        return this._graphs.size;
    }
}