// ============================================================
// NodeStructure/components/live.js — the receiving end of the LIVE LINK (D-156)
//   live_system   (io) for every input the node names in config.live_system.inputs: what the live Succy node on that wire outputs
//                 NOW, reduced — { <input>: { state, src, width, height, info, why, from }, sig }. state:
//                   live    = here it is (src = a data URL, width/height = its real size, info = what the source adds: file name...)
//                   loading = asked, on its way · wait = the source can't say yet (why: "the Load has no picture") ·
//                   none    = no live node on that wire (not wired, or a node only a Run fills: the old rules apply)
//                 Re-reads the wires every 400 ms and asks the Python only when a chain changed; the answer is shared by every node
//                 that looks at the same chain. ready_system and peek_system read the same answers (LiveLink.stateFor).
//   config.live_system.self = [output names]: the node's OWN outputs as they are now, under .self.<output> (a node that shows what
//                 it will hand out, e.g. Load's resized result); config.live_system.when pauses them while nobody looks (see `holds`).
// A node only flags its inputs. Succubus was here — she hears you change your mind before you've finished changing it.
// ============================================================
import { piece } from "../catalog/registry.js";
import { C, ex } from "../catalog/kit.js";
import { LiveLink } from "../runtime/live-link.js";
import { ShotFeed } from "../runtime/shot-feed.js";

const NONE = Object.freeze({ state: "none", src: "", width: 0, height: 0, info: null, why: "" });
const inputsOf = (api) => { const l = api.cfg?.("live_system")?.inputs; return Array.isArray(l) ? l.map(String) : []; };
const maxOf = (api) => Math.max(256, Math.min(4096, Number(api.cfg?.("live_system")?.max) || 1536));
// `when` (JSON): { state: [keys], native: { name: [values] } } — the own outputs are asked while ANY of them holds (a state key true,
// a native at one of the values); no `when` = always
const holds = (api, w) => {
    if (!w || typeof w !== "object") return true;
    if ((w.state || []).some((k) => !!api.state.get(k))) return true;
    return Object.entries(w.native || {}).some(([k, vals]) => (Array.isArray(vals) ? vals : [vals]).includes(api.native.get(k)));
};
const selfOf = (api) => { const c = api.cfg?.("live_system") || {}; return Array.isArray(c.self) && holds(api, c.when) ? c.self.map(String) : []; };
const SELF = "@";                       // own outputs are remembered as "@<output>" (an input can't be called that)

const liveOf = (api) => {
    const me = api.liveNode?.() || api.node;
    const out = { sig: "" };
    const sig = [];
    for (const input of inputsOf(api)) {
        const st = LiveLink.stateFor(me, input);
        out[input] = st ? { ...NONE, ...st } : NONE;
        sig.push(`${input}:${out[input].state}:${out[input].sig || ""}`);
    }
    out.self = {};
    const own = Array.isArray(api.cfg?.("live_system")?.self) ? api.cfg("live_system").self.map(String) : [];
    for (const o of own) {
        const st = LiveLink.selfState(me, SELF + o);
        out.self[o] = st ? { ...NONE, ...st } : NONE;
        sig.push(`@${o}:${out.self[o].state}:${out.self[o].sig || ""}`);
    }
    out.sig = sig.join("|");
    return out;
};
liveOf.ensure = (api) => {
    const seen = new Map();             // input -> the chain signature last asked for
    const tick = () => {
        const me = api.liveNode?.() || api.node;
        if (!me || me.flags?.collapsed) return;
        let changed = false;
        const ask = (key, spec, output, node, prev, put) => {
            const sig = LiveLink.sigOf(spec, node) + "|" + output;
            if (seen.get(key) === sig) return;
            seen.set(key, sig);
            // a node rebuilt by Ctrl+Z asks again for the very same chain: the picture it remembers is already right, so it stays put
            // (no new src = no reload of the view = the veil does not blink off and on)
            if (prev?.state === "live" && prev.src && prev.sig === sig) return;
            changed = true;
            // the old picture stays up while the new one comes: no black flash between two frames
            put({ ...(prev?.src ? prev : {}), state: prev?.src ? "live" : "loading", sig, from: { ...spec, output } });
            LiveLink.view(spec, output, maxOf(api), sig).then((v) => {
                if (seen.get(key) !== sig) return;                         // a newer chain already went out
                put(v.ready
                    ? { state: "live", src: v.src, empty: !!v.empty, width: v.width, height: v.height, info: v.info, why: "", sig, from: { ...spec, output } }
                    : { state: "wait", src: "", width: 0, height: 0, info: null, why: v.why, need: v.need, sig, from: { ...spec, output } });
                api.refresh();
            });
        };
        const own = selfOf(api);
        if (own.length && LiveLink.isLiveType(me.type)) {
            const spec = LiveLink.specOf(me);
            for (const o of own) ask(SELF + o, spec, o, me, LiveLink.selfState(me, SELF + o), (st) => LiveLink.remember(me, SELF + o, st));
        }
        for (const input of inputsOf(api)) {
            const src = LiveLink.sourceOf(me, input);
            if (!src) { if (seen.has(input)) { seen.delete(input); changed = true; } continue; }
            ask(input, LiveLink.specOf(src.node), src.output, src.node, LiveLink.stateFor(me, input), (st) => LiveLink.remember(me, input, st));
        }
        if (changed) api.refresh();
    };
    api.onDispose(LiveLink.subscribe(() => { seen.clear(); tick(); }));
    api.onDispose(ShotFeed.subscribe(tick));
    api.every(tick, 400);
    queueMicrotask(tick);
};
piece(C("live_system", {
    scopo: "LIVE LINK: what the live Succy node on each named input outputs NOW (reduced picture, state, why it waits), no Queue.",
    natura: "works", dominio: "runtime", estado: "draft", tag: ["graph", "state", "input", "preview", "live"], props: {},
    esempio: ex({ t: "label_element", text: "{{$live.live_system.sig}}" }),
}), liveOf);
