// ============================================================
// Succy_CanvasMenu.js — the right-click on the empty canvas, on top of ComfyUI's own menu (D-201)
//   🛑 Force Stop Queue ........ while something runs: queue cleared + interrupt, then if the job won't listen an interrupt
//                                thrown inside the worker, then a reboot offered.  ▶️ Queue when nothing runs (the Run button)
//   ✨ Free VRAM — soft ........ empties the CUDA cache, the models stay loaded (/succy/menu/free_soft)
//   🔥 Free VRAM — unload all .. ComfyUI's /free: every model unloaded + the node cache dropped
//   ⏻ Reboot ComfyUI ........... restarts the server WITHOUT a new browser tab: THIS tab waits and reloads itself (red power icon)
//   ──
//   💎 Succy - Primitive / 📄 Succy - Preview: dropped where you clicked
// Backend: Succy_Common/succy_canvas_menu.py. Only adds entries: ComfyUI's menu below is left exactly as it was.
// ============================================================
import { app } from "../../scripts/app.js";
import { KILLED } from "./lib/killswitch.js";

const TAG = "[Succy Menu]";
const DROPS = [
    { icon: "💎", label: "Succy - Primitive", type: "Succy_Primitive" },
    { icon: "📄", label: "Succy - Preview", type: "Succy_Preview_Anything_&_Convert" },
];

/* ---------- small helpers ---------- */
const wait = (ms) => new Promise((r) => setTimeout(r, ms));
const api = () => globalThis.comfyAPI?.api?.api || app.api || null;
async function call(route, body) {
    const opt = body === undefined ? { method: "GET", cache: "no-store" }
        : { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) };
    const a = api();
    const r = a?.fetchApi ? await a.fetchApi(route, opt) : await fetch(route, opt);
    if (!r.ok) throw new Error(`${route}: HTTP ${r.status}`);
    const t = await r.text();
    try { return t ? JSON.parse(t) : {}; } catch (_) { return {}; }
}
const status = () => call("/succy/menu/status");
const vramFree = async () => { try { return (await call("/succy/vram/stats")).free; } catch (_) { return null; } };
function toast(severity, summary, detail, life = 4000) {
    try { if (app.extensionManager?.toast?.add) { app.extensionManager.toast.add({ severity, summary, detail, life }); return; } } catch (_) { /* below */ }
    console.log(`${TAG} ${summary}: ${detail}`);
}
async function confirmBox(title, message) {
    try {
        const d = app.extensionManager?.dialog;
        if (d?.confirm) return !!(await d.confirm({ title, message, type: "default" }));
    } catch (_) { /* below */ }
    return window.confirm(`${title}\n\n${message}`);
}
const freedText = (before, after) => (before == null || after == null) ? ""
    : ` · ${Math.max(0, after - before).toFixed(2)} GB freed (${after.toFixed(2)} GB free)`;

/* ---------- actions ---------- */
async function freeSoft() {
    try {
        const b = await vramFree();
        await call("/succy/menu/free_soft", {});
        toast("success", "Free VRAM — soft", "CUDA cache emptied, models kept" + freedText(b, await vramFree()));
    } catch (e) { toast("error", "Free VRAM — soft", String(e?.message || e)); }
}

async function freeHard() {
    try {
        const b = await vramFree(), s = await status().catch(() => ({}));
        await call("/free", { unload_models: true, free_memory: true });
        if (s.running) { toast("info", "Free VRAM — unload all", "Asked: it happens as soon as the running job ends."); return; }
        await wait(1500);                                      // ComfyUI's worker picks the request up within ~1 s
        toast("success", "Free VRAM — unload all", "Models unloaded, cache dropped" + freedText(b, await vramFree()));
    } catch (e) { toast("error", "Free VRAM — unload all", String(e?.message || e)); }
}

async function clearQueue() {
    await call("/queue", { clear: true });
    await call("/interrupt", {});
}

// running === 0 within ms? (the worker answers between two nodes / sampler steps)
async function stoppedWithin(ms) {
    const t0 = Date.now();
    let s = null;
    while (Date.now() - t0 < ms) {
        try { s = await status(); if (!s.running) return { ok: true, s }; if (s.worker === false) return { ok: false, s }; } catch (_) { /* server busy */ }
        await wait(400);
    }
    return { ok: false, s };
}

async function forceStop() {
    try {
        await clearQueue();
        let r = await stoppedWithin(4000);
        if (r.ok) { toast("success", "Force Stop Queue", "Stopped: queue cleared, job interrupted."); return; }
        // the job ignores the interrupt flag: throw the interrupt INSIDE the worker, a few times (a long C call must return first)
        for (let i = 0; i < 3 && !r.ok && r.s?.worker !== false; i++) {
            await call("/succy/menu/force_stop", { step: "throw" });
            r = await stoppedWithin(2500);
        }
        if (r.ok) { toast("success", "Force Stop Queue", "Stopped: the stuck job was forced out."); return; }
        const why = r.s?.worker === false ? "The worker died while being stopped." : "The job is stuck in something that cannot be stopped from inside.";
        if (await confirmBox("ComfyUI is stuck", `${why}\nReboot ComfyUI now? This tab reloads by itself.`)) reboot(true);
    } catch (e) { toast("error", "Force Stop Queue", String(e?.message || e)); }
}

/* ---------- reboot in THIS tab ---------- */
let REBOOTING = false;
function overlay() {
    const el = document.createElement("div");
    el.id = "succy-reboot-overlay";
    el.style.cssText = "position:fixed;inset:0;z-index:2147483646;display:flex;align-items:center;justify-content:center;"
        + "background:rgba(8,8,14,.82);color:#e8e8f0;font:600 16px system-ui,sans-serif;flex-direction:column;gap:12px";
    el.innerHTML = `<div style="font-size:34px">🔄</div><div data-t>Rebooting ComfyUI…</div><div data-s style="font-weight:400;font-size:12px;opacity:.7"></div>`;
    document.body.appendChild(el);
    return {
        set: (t, s = "") => { el.querySelector("[data-t]").textContent = t; el.querySelector("[data-s]").textContent = s; },
        button: (label, fn) => { const b = document.createElement("button"); b.textContent = label; b.style.cssText = "padding:6px 14px;border-radius:6px;cursor:pointer"; b.onclick = fn; el.appendChild(b); },
    };
}

async function reboot(confirmed = false) {
    if (REBOOTING) return;
    try {
        if (!confirmed) {
            const s = await status().catch(() => ({}));
            const busy = (s.running || 0) + (s.pending || 0);
            if (busy && !(await confirmBox("Reboot ComfyUI", `There ${busy === 1 ? "is 1 job" : `are ${busy} jobs`} in the queue: they will be lost. Reboot anyway?`))) return;
        }
        if (window.electronAPI?.restartApp) { window.electronAPI.restartApp(); return; }   // ComfyUI Desktop restarts itself
        REBOOTING = true;
        const ui = overlay();
        let boot = null;
        try { boot = (await status()).boot; } catch (_) { /* already down */ }
        await call("/succy/menu/reboot", {});
        ui.set("Rebooting ComfyUI…", "the server is restarting, this tab reloads by itself");
        const t0 = Date.now();
        while (Date.now() - t0 < 300000) {
            await wait(1000);
            try { const s = await status(); if (s.boot && s.boot !== boot) { ui.set("Back!", "reloading…"); location.reload(); return; } } catch (_) { /* still down */ }
        }
        ui.set("ComfyUI did not come back", "look at the console window; then reload this tab");
        ui.button("Reload", () => location.reload());
    } catch (e) {
        REBOOTING = false;
        document.getElementById("succy-reboot-overlay")?.remove();
        toast("error", "Reboot ComfyUI", String(e?.message || e));
    }
}

/* ---------- drop a node where the menu opened ---------- */
function drop(canvas, type, pos) {
    const LG = globalThis.LiteGraph, g = canvas?.graph || app.graph;
    const n = LG?.createNode?.(type);
    if (!n || !g) { toast("warn", "Succy", `${type} is not available.`); return; }
    n.pos = [pos[0], pos[1]];
    g.add(n);
    try { canvas.selectNode?.(n); } catch (_) { /* selection is a bonus */ }
    try { canvas.setDirty?.(true, true); } catch (_) { /* next frame draws it */ }
}

/* ---------- is something in the queue? (the menu is built synchronously: kept up to date by ComfyUI's status event) ---------- */
let QUEUED = 0;
function trackQueue() {
    const a = api();
    a?.addEventListener?.("status", (e) => { QUEUED = e?.detail?.exec_info?.queue_remaining ?? 0; });
    status().then((s) => { QUEUED = (s.running || 0) + (s.pending || 0); }).catch(() => {});
}
async function queueNow() {
    try { await app.queuePrompt(0, 1); } catch (e) { toast("error", "Queue", String(e?.message || e)); }
}

// Menu entries are plain text, and every emoji font draws its glyphs with its own width and baseline: the icons
// wobble. Once the menu is on screen each of OUR icons goes into the same fixed box, centered; the power one in red.
const POWER = "⏻";
const ICONS = ["🛑", "▶️", "✨", "🔥", POWER, "💎", "📄"];
const BOX = "display:inline-flex;align-items:center;justify-content:center;flex:0 0 1.3em;width:1.3em;margin-right:.35em;line-height:1";
function paintIcons() {
    requestAnimationFrame(() => {
        for (const el of document.querySelectorAll(".litecontextmenu .litemenu-entry")) {
            const t = el.firstChild;
            if (t?.nodeType !== 3) continue;
            const icon = ICONS.find((i) => t.nodeValue.startsWith(i + " "));
            if (!icon) continue;
            const i = document.createElement("span");
            i.textContent = icon;
            i.style.cssText = BOX + (icon === POWER ? ";color:#ff3b3b;font-weight:700;text-shadow:0 0 6px rgba(255,59,59,.6)" : "");
            t.nodeValue = t.nodeValue.slice(icon.length + 1);
            el.insertBefore(i, t);
            el.style.display = "flex";                         // icon box and text centered on the same line
            el.style.alignItems = "center";
        }
    });
}

/* ---------- menu entries ---------- */
function items(canvas) {
    const p = canvas?.graph_mouse ? [canvas.graph_mouse[0], canvas.graph_mouse[1]] : [0, 0];
    const known = globalThis.LiteGraph?.registered_node_types || {};
    paintIcons();
    return [
        QUEUED > 0 ? { content: "🛑 Force Stop Queue", callback: () => { forceStop(); } }
            : { content: "▶️ Queue", callback: () => { queueNow(); } },
        { content: "✨ Free VRAM — soft", callback: () => { freeSoft(); } },
        { content: "🔥 Free VRAM — unload all", callback: () => { freeHard(); } },
        { content: `${POWER} Reboot ComfyUI`, callback: () => { reboot(); } },
        null,
        ...DROPS.filter((d) => known[d.type]).map((d) => ({ content: `${d.icon} ${d.label}`, callback: () => drop(canvas, d.type, p) })),
        null,
    ];
}

// ONE copy per menu, whichever way the frontend asks: the old prototype hook (our entries on top) or the newer
// getCanvasMenuItems extension hook. Both run in the same synchronous menu build, so a short stamp tells them apart.
let STAMP = 0;
const fresh = () => performance.now() - STAMP < 50;

function patchPrototype() {
    const P = (globalThis.LGraphCanvas || app.canvas?.constructor)?.prototype;
    const orig = P?.getCanvasMenuOptions;
    if (typeof orig !== "function" || orig.__succyMenu) return;
    const wrapped = function (...args) {
        if (fresh()) return orig.apply(this, args);            // the extension hook already gave this menu its copy
        STAMP = performance.now();                             // stamped BEFORE: a hook called from inside orig stays quiet
        const base = orig.apply(this, args);
        return Array.isArray(base) ? [...items(this), ...base] : base;
    };
    wrapped.__succyMenu = true;
    P.getCanvasMenuOptions = wrapped;
}

if (!KILLED) app.registerExtension({
    name: "Succy.CanvasMenu",
    setup() {
        try { trackQueue(); } catch (_) { /* the entry just stays "Queue" */ }
        try { patchPrototype(); } catch (e) { console.warn(TAG, "menu hook not installed:", e); }
    },
    getCanvasMenuItems(canvas) {
        if (fresh()) return [];
        STAMP = performance.now();
        return items(canvas || app.canvas).slice(0, -1);
    },
});
