// ============================================================
// Governor/errors.js — CONTROL department: collects the pack's errors and tells you WHERE they are. She always tells.
// ------------------------------------------------------------
// Sources: window "error" / "unhandledrejection" + console.warn/error (pack messages only:
// [NodeStructure]/[SurvivalKit]/[Succy...] prefix, or a stack that goes through the pack's files).
// For each entry: department (Survival / Builder / Governor / Glue) + file:line from the first pack frame.
// If one of the arguments is an Error, ITS stack is used (= where it was really born, not who logged it).
// Bundled (D-139) every frame says succy-pack.js: the entry first shows the bundle position, then the source map
// (fetched on the first error only, lib/sourcemap.js) turns it into the real file:line and subscribers hear it again.
// Imports only the kill switch and the map reader. Ring of 80 entries. See DECISIONS D-56.
// ============================================================

import { KILLED } from "../lib/killswitch.js";
import { SrcMap, BUNDLE } from "../lib/sourcemap.js";
const PACK = "/extensions/ComfyUI-Succy-Pack/";
const MAX = 80;
const LIST = [];
const subs = new Set();
const HELPERS = /(^|\/)Governor\/errors\.js$/;     // frames to skip (ourselves), tested on the source path
const RAW = new WeakMap();                         // entry -> stack still waiting for the source map

export function deptOf(path) {
    if (!path || path === BUNDLE) return "?";
    if (path.startsWith("SurvivalKit/") || path.startsWith("lib/")) return "Survival";
    if (path.startsWith("NodeStructure/")) return "Builder";
    if (path.startsWith("Governor/")) return "Governor";
    return "Colla";                                     // node/extension files in the root of js/
}

// first pack frame in a stack: { path: "NodeStructure/fx/native.js", line, col, fn } (+ raw:true while the bundle map is not loaded)
export function whereOf(stack) {
    if (typeof stack !== "string") return null;
    for (const f of SrcMap.frames(stack)) {
        const i = f.url.indexOf(PACK);
        if (i < 0) continue;
        let path = decodeURIComponent(f.url.slice(i + PACK.length)), line = f.line, col = f.col, raw = false;
        if (BUNDLE && path === BUNDLE) {
            if (!SrcMap.ready) return { path, line, col, fn: f.fn, raw: true };
            const o = SrcMap.locate(line, col);
            if (!o) continue;
            ({ path, line, col } = o);
        }
        if (HELPERS.test(path)) continue;
        return { path, line, col, fn: f.fn, raw };
    }
    return null;
}

// stack minus its first pack frame (= the caller that built it here: the console wrapper, report())
const dropOwnFrame = (st) => { const l = String(st || "").split("\n"); const k = l.findIndex((x) => x.includes(PACK)); if (k >= 0) l.splice(k, 1); return l.join("\n"); };

function resolveLater() {
    SrcMap.load().then(() => {
        let last = null;
        for (const e of LIST) {
            const st = RAW.get(e);
            if (st === undefined) continue;
            RAW.delete(e);
            const w = whereOf(st);
            e.dept = deptOf(w?.path); e.where = w ? `${w.path}:${w.line}` : "?"; e.fn = w?.fn || ""; last = e;
        }
        if (last) for (const fn of subs) { try { fn(last); } catch (_) {} }
    }).catch(() => {});
}

// Errors a selfTest provokes ON PURPOSE (D-200): it opens a short window `globalThis.__succyExpectErrors = { until, re }` and the
// matching messages are counted apart (Errors.expected) instead of landing in the list as if something broke. A staged scream isn't news.
let EXPECTED = 0;
function expected(msg) {
    const x = globalThis.__succyExpectErrors;
    if (!x || !(x.re instanceof RegExp) || !(Date.now() < x.until)) return false;
    return x.re.test(String(msg));
}
function push(level, msg, stack, extra = {}) {
    if (extra.kind === "console" && expected(msg)) { EXPECTED++; return; }
    const w = whereOf(stack);
    const e = { t: Date.now(), level, msg: String(msg).slice(0, 300), dept: deptOf(w?.path), where: w ? `${w.path}:${w.line}` : "?", fn: w?.fn || "", ...extra };
    const last = LIST[LIST.length - 1];
    if (last && last.msg === e.msg && last.where === e.where) { last.n = (last.n || 1) + 1; last.t = e.t; }
    else { LIST.push(e); if (LIST.length > MAX) LIST.shift(); if (w?.raw) { RAW.set(e, stack); resolveLater(); } }
    for (const fn of subs) { try { fn(e); } catch (_) {} }
}

const ours = (s) => typeof s === "string" && /^\s*\[(NodeStructure|SurvivalKit|Succy|Governor)/.test(s);
const textOf = (args) => args.map((a) => (a instanceof Error ? `${a.name}: ${a.message}` : typeof a === "string" ? a : (() => { try { return JSON.stringify(a); } catch (_) { return String(a); } })())).join(" ");

let installed = false;
export function installErrorWatch() {
    if (installed) return;
    installed = true;
    window.addEventListener("error", (ev) => {
        const st = ev.error?.stack || `at ${ev.filename}:${ev.lineno}:${ev.colno}`;
        if (!String(st).includes(PACK)) return;
        push("error", ev.message || ev.error?.message || "error", st, { kind: "uncaught" });
    }, true);
    window.addEventListener("unhandledrejection", (ev) => {
        const r = ev.reason, st = r?.stack || "";
        if (!String(st).includes(PACK)) return;
        push("error", r?.message || String(r), st, { kind: "promise" });
    });
    for (const level of ["warn", "error"]) {
        const orig = console[level];
        if (typeof orig !== "function" || orig.__succyWatch) continue;
        const wrap = function (...args) {
            try {
                const errArg = args.find((a) => a instanceof Error);
                const here = dropOwnFrame(new Error().stack);                  // minus this wrapper: bundled, it lives in the same file as everyone
                if (ours(args[0]) || (errArg && String(errArg.stack).includes(PACK)) || (!errArg && level === "error" && here.includes(PACK) && whereOf(here))) {
                    push(level, textOf(args), errArg?.stack && String(errArg.stack).includes(PACK) ? errArg.stack : here, { kind: "console" });
                }
            } catch (_) {}
            return orig.apply(this, args);
        };
        wrap.__succyWatch = true;
        console[level] = wrap;
    }
}

export const Errors = {
    list: () => LIST.slice(),
    clear: () => { LIST.length = 0; },
    expected: () => EXPECTED,                // provoked on purpose by a selfTest, not listed
    subscribe: (fn) => { subs.add(fn); return () => subs.delete(fn); },
    // summary per department/file: where to look first
    summary: () => { const m = new Map(); for (const e of LIST) { const k = `${e.dept} · ${e.where.replace(/:\d+$/, "")}`; m.set(k, (m.get(k) || 0) + (e.n || 1)); } return [...m].sort((a, b) => b[1] - a[1]).map(([k, n]) => ({ where: k, count: n })); },
    report: (msg, stack) => push("report", msg, stack || new Error().stack, { kind: "manual" }),
};
if (!KILLED) installErrorWatch();          // it wraps console.warn / console.error: a patch, so the kill switch skips it
