// ============================================================
// lib/smart-cache-apply.js — D-213: the prompt side of SmartCache, pure (no DOM, no ComfyUI: node runs it in the tests)
// ------------------------------------------------------------
// request(): which nodes of the API prompt the Python may precompute (policy "pure") and which of their outputs are used.
// apply(): with the Python's answer, every used wire out of a precomputed node goes through a hidden Succy_Value holding ONLY
// that value (id "<id>_v<slot>"): same value = same constant = ComfyUI's cache keeps the whole branch after it. A wire out of a
// ROUTE node (a switch that hands one input out untouched) goes straight to the input it picked, through as many switches as needed.
// The original prompt is never changed (a copy goes out); a wire without an answer stays exactly as it was.
// She hands each lover a sealed envelope: same note inside, same envelope, nobody needs to call her again.
// ============================================================

export const TWIN_CLASS = "Succy_Value";

const isLink = (v) => Array.isArray(v) && v.length === 2;

/** output = the API prompt, isPure(class_type) -> {nodes, want}: the pure / route nodes (all of them: a chain needs its upstream) + used slots */
export function request(output, isPure) {
    const nodes = {}, want = {};
    if (!output || typeof output !== "object") return { nodes, want };
    for (const [id, node] of Object.entries(output)) if (node && isPure(node.class_type)) nodes[id] = { class_type: node.class_type, inputs: node.inputs || {} };
    for (const node of Object.values(output)) {
        for (const v of Object.values(node?.inputs || {})) {
            if (!isLink(v) || !nodes[String(v[0])]) continue;
            const s = (want[String(v[0])] ||= []), k = Number(v[1]);
            if (!s.includes(k)) s.push(k);
        }
    }
    return { nodes, want };
}

/** output + answer {values: {id: {slot: code}}, routes: {id: {slot: input}}, ui: [ids]} -> {output: a rewired copy, twins, rewired,
 *  routed, kept, bypassed: [route ids nobody reads any more]} */
export function apply(output, answer) {
    const res = { output, twins: 0, rewired: 0, routed: 0, kept: 0, bypassed: [] };
    if (!output || typeof output !== "object") return res;
    const vals = answer?.values || {}, ui = new Set((answer?.ui || []).map(String)), routes = answer?.routes || {};
    const out = { ...output };
    // a wire into a route node's routed output -> the wire into the input it picked (a chain of switches, a loop guard)
    const follow = (v) => {
        let link = v, hops = 0;
        while (hops++ < 32) {
            const name = routes[String(link[0])]?.[String(link[1])], nxt = name && output[String(link[0])]?.inputs?.[name];
            if (!isLink(nxt)) break;
            link = nxt;
        }
        return link;
    };
    for (const [id, node] of Object.entries(output)) {
        const ins = node?.inputs;
        if (!ins || typeof ins !== "object") continue;
        let copy = null;
        for (const [name, v0] of Object.entries(ins)) {
            if (!isLink(v0)) continue;
            const v = follow(v0), moved = v !== v0;
            if (moved) { copy = copy || { ...ins }; copy[name] = v; res.routed++; }
            const src = String(v[0]), slot = String(v[1]);
            if (!(src in vals) && !ui.has(src)) continue;                 // not a precomputed node: not our business
            const code = ui.has(src) ? undefined : vals[src]?.[slot];
            if (typeof code !== "string") { if (!moved) res.kept++; continue; }
            const tid = `${src}_v${slot}`;
            if (!out[tid]) {
                out[tid] = { class_type: TWIN_CLASS, inputs: { value: code }, _meta: { title: `${output[src]?._meta?.title || output[src]?.class_type || src} · out ${slot}` } };
                res.twins++;
            }
            copy = copy || { ...ins };
            copy[name] = [tid, 0];
            res.rewired++;
        }
        if (copy) out[id] = { ...node, inputs: copy };
    }
    // route nodes that nobody reads any more: ComfyUI won't run them, the browser shows their choice itself (route_ui)
    const read = new Set();
    for (const node of Object.values(out)) for (const v of Object.values(node?.inputs || {})) if (isLink(v)) read.add(String(v[0]));
    res.bypassed = Object.keys(routes).filter((id) => !read.has(id));
    res.output = out;
    return res;
}
