// ============================================================
// pieces/actions.js — the kit's GENERIC actions ($actions.<name>, with `args`)
//   copy_system  download_system  flip_node  set_node  focus_graph
//   reload_system  fit_mask  reset_node
// Signature: (api, ev, el, item, args). The args arrive already resolved ($ref/template evaluated).
// ============================================================
import { LiveLink } from "../runtime/live-link.js";
import { piece } from "../catalog/registry.js";
import { C, ex, E, S, N, B, R, K, J } from "../catalog/kit.js";
import { INSTANCES } from "../core/runtime.js";
import { writePersisted } from "../core/heights.js";
import { impl } from "../catalog/registry.js";

const BTN = (id, text, on) => ({ t: "button_element", id, text, on });
const actEx = (name, args, more = {}) => ex(BTN("b", "go", { click: { do: "$actions." + name, args } }), more);

// a ComfyUI route, POSTing the node as it is NOW ({widgets, linked}, D-117) plus `body` (extra fields, e.g. the Crop on a wire, D-124)
const routeFetch = (api, route, post, body) => {
    const node = api.liveNode?.() || api.node;
    const path = String(route).replace(/\{id\}/g, encodeURIComponent(node?.id ?? ""));
    if (!post) return globalThis.app.api.fetchApi(path);
    const snap = globalThis.SurvivalKit?.nodePorts?.snapshot?.(node) || { widgets: {}, linked: [] };
    return globalThis.app.api.fetchApi(path, { method: "POST", headers: { "Content-Type": "application/json" },
        // `from` (D-156): the live Succy nodes behind its wires ride along, so the Python computes from what they send right now
        body: JSON.stringify({ widgets: snap.widgets, linked: snap.linked, from: LiveLink.fromOf(node), ...(body && typeof body === "object" ? body : {}) }) });
};
const errOf = async (r) => { let m = `HTTP ${r.status}`; try { m = (await r.json()).error || m; } catch (_) { /* not json */ } return m; };
const toastWarn = (summary, detail) => { try { globalThis.app?.extensionManager?.toast?.add?.({ severity: "warn", summary, detail, life: 4000 }); } catch (_) { /* no toast here */ } };

const flash = (api, key, ok) => {
    api.cache.set(key, ok ? "✓" : "✗"); api.refresh();
    api.after(() => { api.cache.set(key, ""); api.refresh(); }, 1500);
};

piece(C("copy_system", {
    scopo: "Copies a text or an image (from a URL) to the clipboard and shows a ✓/✗ flash in the cache.", natura: "works", dominio: "runtime", estado: "draft",
    tag: ["action", "clipboard"],
    props: { kind: E(["text", "image"], "what to copy", "text"), text: R("text to copy"), url: R("image URL (kind image)"), flash: S("cache key for the ✓/✗ flash", "copyFlash"),
        route: S("kind image, as an alternative to url: ComfyUI route that answers a PNG, {id} = node id (D-124)"), post: B("with `route`: POST of the node as it is NOW (like download_system)", false),
        body: R("with `post`: extra fields in the body (e.g. {crop: $live.peek_system.post})") },
    esempio: actEx("copy_system", { kind: "text", text: "x", flash: "cf" }),
}), async (api, ev, el, item, a = {}) => {
    ev?.stopPropagation?.();
    const key = a.flash || "copyFlash";
    try {
        if (a.kind === "image" && a.route) {
            // the clipboard item is handed over NOW (still inside the click) with a promise of the PNG: the browser keeps the permission
            if (!globalThis.isSecureContext || !navigator.clipboard?.write) throw new Error("the browser only copies pictures on localhost / https: use Download");
            let msg = "";
            const png = (async () => { const r = await routeFetch(api, a.route, a.post, a.body); if (!r.ok) { msg = await errOf(r); throw new Error(msg); } return new Blob([await r.arrayBuffer()], { type: "image/png" }); })();
            try { await navigator.clipboard.write([new ClipboardItem({ "image/png": png })]); }
            catch (e) { throw new Error(msg || e?.message || String(e)); }
        } else if (a.kind === "image" && a.url) {
            const blob = await (await fetch(a.url)).blob();
            await navigator.clipboard.write([new ClipboardItem({ [blob.type || "image/png"]: blob })]);
        } else await navigator.clipboard.writeText(String(a.text ?? ""));
        flash(api, key, true);
    } catch (e) { api.log?.("copy failed", e); if (a.route) toastWarn("Copy", String(e?.message || e)); flash(api, key, false); }
});

piece(C("download_system", {
    scopo: "Downloads a file from a URL or from a ComfyUI route (also from a menu entry) and shows a ✓/✗ flash; server errors as a toast.", natura: "works", dominio: "runtime", estado: "draft",
    tag: ["action", "file"],
    props: {
        url: R("URL to download"), route: S("alternatively: ComfyUI route (fetchApi), {id} = node id (D-115)"),
        name: S("file name (empty: the server one, Content-Disposition)", "download"), flash: S("cache key for the flash", "dlFlash"),
        post: B("with `route`: POST {widgets: node widget values, linked: connected inputs} — the server computes from the node as it is NOW (D-117)", false),
        body: R("with `post`: extra fields in the body (e.g. {crop: $live.peek_system.post}, D-124)"),
    },
    esempio: actEx("download_system", { url: "data:image/gif;base64,R0lGODlhAQABAAAAACw=", name: "x.gif" }),
}), async (api, ev, el, item, a = {}) => {
    ev?.stopPropagation?.();
    // args win; from a menu_float_list item the fields come on the item itself (a list item has no args)
    const pick = (k) => (a && a[k] !== undefined ? a[k] : item?.[k]);
    const url = pick("url"), route = pick("route");
    if (!url && !route) return;
    const key = pick("flash") || "dlFlash";
    const toast = (detail) => toastWarn("Download", detail);
    try {
        const r = route ? await routeFetch(api, route, pick("post"), pick("body")) : await fetch(url);
        if (!r.ok) { toast(await errOf(r)); flash(api, key, false); return; }
        const name = pick("name") || /filename="([^"]+)"/.exec(r.headers.get("Content-Disposition") || "")?.[1] || "download";
        const bu = URL.createObjectURL(await r.blob());
        const link = document.createElement("a"); link.href = bu; link.download = name;
        document.body.appendChild(link); link.click(); link.remove();
        api.after(() => URL.revokeObjectURL(bu), 1500);
        flash(api, key, true);
    } catch (e) { api.log?.("download failed", e); toast("Download failed: " + (e?.message || e)); flash(api, key, false); }
});

piece(C("flip_node", {
    scopo: "Toggles a boolean node state key (with a default when not set yet) or a native boolean widget (`native`).", natura: "works", estado: "draft",
    tag: ["action", "state"],
    props: { key: K("boolean state key"), native: S("alternative to key: name of a native bool widget (e.g. use_choice)"), default: B("value assumed if the key is empty", false) },
    esempio: actEx("flip_node", { key: "f" }, { state: { f: { policy: "ui", default: false } } }),
}), (api, ev, el, item, a = {}) => {
    // a native widget gets flipped in place (the Python reads it); otherwise the kit state key — one flick and she switches sides
    if (a.native) { const v = api.native.get(a.native); api.native.set(a.native, !(v === true || v === "true")); return; }
    if (!a.key) return;
    const cur = api.state.get(a.key);
    const eff = cur === undefined || cur === null ? !!a.default : !!cur;
    api.state.set(a.key, !eff);
});

piece(C("set_node", {
    scopo: "Writes a value into a node state key or a native widget (unless `unless`) and, if asked, marks the graph as modified.", natura: "works", estado: "draft",
    tag: ["action", "state"],
    props: { key: K("state key"), native: S("alternative to key: name of a native widget (e.g. box)"), value: { ...R("value to write"), required: true }, unless: R("if true it does nothing"), change: B("calls graph.change()", false) },
    esempio: actEx("set_node", { key: "v", value: "uno", change: true }, { state: { v: { policy: "ui" } } }),
}), (api, ev, el, item, a = {}) => {
    if (a.unless) return;
    // a native widget gets the value in place (the Python reads it) — same door as flip_node
    if (a.native) { if (api.native.get(a.native) !== a.value) api.native.set(a.native, a.value); return; }
    if (!a.key) return;
    if (api.state.get(a.key) === a.value) return;
    api.state.set(a.key, a.value);
    if (a.change) { try { api.node.graph?.change?.(); } catch (_) {} }
});

piece(C("focus_graph", {
    scopo: "Centres another node (or native reroute) of the graph and, if given, opens a menu there (closing the current one).", natura: "works", dominio: "graph", estado: "draft",
    tag: ["action", "graph", "navigation"],
    props: { node: { ...R("target node (from a kit $live)"), required: true }, menu: S("menu to open on the target node"), close: S("menu to close on this node") },
    esempio: actEx("focus_graph", { node: "$live.self_node.node", close: "m" }),
}), (api, ev, el, item, a = {}) => {
    const target = a.node;
    if (a.close) api.closeMenu(a.close);
    if (!target) return;
    if (target.reroute) {                                 // native reroute subject: centers the canvas on the dot — all eyes on her
        const cv = globalThis.app?.canvas, r = target.reroute;
        try {
            const dpr = globalThis.devicePixelRatio || 1, sc = cv.ds.scale || 1;
            cv.ds.offset[0] = -r.pos[0] + (cv.canvas.width * 0.5) / (sc * dpr);
            cv.ds.offset[1] = -r.pos[1] + (cv.canvas.height * 0.5) / (sc * dpr);
            cv.setDirty?.(true, true);
        } catch (_) {}
        if (a.menu && typeof target.open === "function") {
            let pt;
            try { const b = cv.canvas.getBoundingClientRect(); pt = { x: b.left + b.width / 2 + 18, y: b.top + b.height / 2 + 12 }; } catch (_) {}
            setTimeout(() => target.open(a.menu, pt ? { point: pt } : {}), 0);     // not api.after: the current menu (and its runtime) closes now
        }
        return;
    }
    try { globalThis.app?.canvas?.selectNode?.(target); globalThis.app?.canvas?.centerOnNode?.(target); } catch (_) {}
    if (a.menu) INSTANCES.get(target)?.api.openMenu(a.menu, { reopen: true });
});

piece(C("reload_system", {
    scopo: "Reloads a kit data source (e.g. effects_system) by calling its reload().", natura: "works", dominio: "runtime", estado: "draft",
    tag: ["action", "data"], props: { name: { ...S("name of the io piece to reload"), required: true } },
    esempio: actEx("reload_system", { name: "effects_system" }),
}), (api, ev, el, item, a = {}) => { const f = impl(a.name, "io"); f?.reload?.(api); });

piece(C("fit_mask", {
    scopo: "On the first loaded image fits the height of a mask to the aspect ratio (persisted).", natura: "works", estado: "draft",
    tag: ["action", "layout", "image"],
    props: {
        state: { ...K("numeric state key of the height"), required: true }, min: N("minimum height of the fit", 160), max: N("maximum height", 640),
        pad: N("spazio aggiunto (px)", 40), done: S("cache key 'already fitted'", "fitDone"), when: R("if defined and false it does nothing"),
    },
    esempio: actEx("fit_mask", { state: "ah", min: 100, max: 300 }, { state: { ah: { policy: "ui" } } }),
}), (api, ev, el, item, a = {}) => {
    const img = ev?.detail?.img || el?.querySelector?.("img");
    if (!img?.naturalWidth) return;
    const done = a.done || "fitDone";
    if (api.cache.get(done) || (a.when !== undefined && !a.when)) return;
    const innerW = Math.max(120, (api.node.size?.[0] || 240) - 40);
    const area = Math.round(Math.min(a.max ?? 640, Math.max(a.min ?? 160, innerW * img.naturalHeight / img.naturalWidth + (a.pad ?? 40))));
    api.cache.set(done, true);
    const rt = INSTANCES.get(api.node);
    if (rt) writePersisted(rt, { kind: "state", key: a.state, raw: "$state." + a.state }, area, true);
    api.relayout();
});

piece(C("reset_node", {
    scopo: "Resets a numeric state key (cache+local+state) to a value and, if given, the node width.", natura: "works", estado: "draft",
    tag: ["action", "layout", "state"],
    props: { key: { ...K("numeric state key to reset"), required: true }, value: { ...N("valore"), required: true }, width: N("node width (px); absent = unchanged") },
    esempio: actEx("reset_node", { key: "h", value: 100 }, { state: { h: { policy: "ui" } } }),
}), (api, ev, el, item, a = {}) => {
    const rt = INSTANCES.get(api.node);
    if (rt && typeof a.value === "number") writePersisted(rt, { kind: "state", key: a.key, raw: "$state." + a.key }, a.value, true);
    if (typeof a.width === "number") {
        try { api.utils.withInternalResize(() => api.node.setSize?.([a.width, api.node.size?.[1] ?? 0])); } catch (_) {}
    }
    api.relayout();
});

void J;
