// bundled build: the node file behind a define() stack = first frame outside the kit, read back from the source map
async function bundledSource(stack) {
    if (!stack || !SrcMap.bundle) return null;
    await SrcMap.load();
    for (const f of SrcMap.frames(stack)) {
        if (f.file !== SrcMap.bundle) continue;
        const o = SrcMap.locate(f.line, f.col);
        if (o && !/^(NodeStructure|SurvivalKit|lib|Governor)\//.test(o.path)) return SrcMap.content(o.path);
    }
    return null;
}

async function catalogTests(NS, rec) {
    const cat = NS.catalog, R = cat.registry, G = cat.grammar;
    const pass = (id, name, d = "") => rec(id, name, "PASS", d);
    const fail = (id, name, d) => rec(id, name, "FAIL", d);

    // C1 registration
    const pr = R.PROBLEMS;
    pr.length ? fail("C1", "valid cards", pr.map((p) => `${p.nome}: ${p.errors.join("; ")}`).join(" || ")) : pass("C1", `all pieces have a valid card (${R.REG.size})`);

    // C2 grammar / dictionary / composition
    {
        const bad = [];
        for (const [n, r] of R.REG) {
            const pn = G.parseName(n);
            if (!pn.ok) bad.push(`${n}: ${pn.error}`);
            for (const u of r.card.uses || []) if (!R.REG.has(u)) bad.push(`${n}: uses '${u}' does not exist`);
            for (const a of r.card.alias || []) if (R.REG.has(a)) bad.push(`${n}: alias '${a}' is also a piece`);
        }
        const cyc = [];
        for (const [n] of R.REG) { const seen = new Set(), st = [n]; while (st.length) { const x = st.pop(); for (const u of R.REG.get(x)?.card.uses || []) { if (u === n) cyc.push(n); if (!seen.has(u)) { seen.add(u); st.push(u); } } } }
        if (cyc.length) bad.push("uses circolare: " + [...new Set(cyc)].join(","));
        bad.length ? fail("C2", "grammatica nomi / alias / uses", bad.join(" || ")) : pass("C2", "names in the grammar, aliases without collisions, valid uses and no cycles");
    }

    // C3 examples: every piece mounts its own example
    {
        const { mountExample } = await import("./catalog/example.js");
        const bad = [];
        for (const [n, r] of R.REG) { let m; try { m = mountExample(r.card); } catch (e) { m = { ok: false, errors: [String(e.message || e)] }; } if (!m.ok) bad.push(`${n}: ${m.errors.join(" ; ")}`); }
        bad.length ? fail("C3", `esempi montati (${R.REG.size - bad.length}/${R.REG.size})`, bad.join(" || ")) : pass("C3", `all examples validate and mount without leaks (${R.REG.size})`);
    }

    // C4 late pieces/CSS (written outside the kit)
    {
        const late = cat.late();
        late.pieces.length || late.css.length ? fail("C4", "no pieces/CSS outside the kit", `pieces: ${late.pieces.join(",")} css: ${late.css.join(",")}`) : pass("C4", "no piece or CSS registered outside the kit");
    }

    // C5 lock of the stable pieces
    try {
        const errs = R.checkLock(LOCK);         // bundled in at build time (D-139): no fetch, no path to get wrong
        errs.length ? fail("C5", "hash of the stable pieces = lock", errs.join(" || ")) : pass("C5", "hash of the stable pieces equal to the lock");
    } catch (e) { rec("C5", "catalog.lock.json", "SKIP", String(e.message || e)); }

    // C6 nodes: valid spec, old names, file hygiene
    for (const [type, info] of R.NODES) {
        const d = NS.defs.get(type) || NS.extensions?.get(type);
        if (d && d.errors.length) fail("C6:" + type, `node '${type}' uses only catalog pieces`, d.errors.slice(0, 4).join(" || "));
        else pass("C6:" + type, `node '${type}' uses only catalog pieces`, `${info.pieces.size} pieces${info.aliasUsed.length ? "; OLD NAMES: " + info.aliasUsed.join(", ") : ""}`);
        let txt = null;
        try { txt = info.src ? await (await fetch(info.src, { cache: "no-store" })).text() : await bundledSource(info.stack); }
        catch (e) { rec("C7:" + type, `igiene file '${type}'`, "SKIP", String(e.message || e)); continue; }
        if (txt == null) { rec("C7:" + type, `igiene file '${type}'`, "SKIP", "source not identifiable"); continue; }
        try {
            const code = txt.replace(/\/\*[\s\S]*?\*\//g, "").replace(/(^|[^:\\])\/\/.*$/gm, "$1");
            const rules = [[/\bdocument\./, "document.*"], [/createElement/, "createElement"], [/\binnerHTML\b/, "innerHTML"], [/registerCss/, "registerCss"], [/\.style\.|cssText/, "hand-made style"], [/\bnew Function\b|\beval\(/, "eval"], [/addEventListener/, "addEventListener (use the kit)"], [/requestAnimationFrame|setInterval|setTimeout/, "direct timers (use api.after/raf)"], [/getComputedStyle|getSelection|navigator\.clipboard|createObjectURL/, "browser API"]];
            const hits = rules.filter(([re]) => re.test(code)).map(([, n]) => n);
            hits.length ? fail("C7:" + type, `igiene file '${type}'`, "in the node file: " + hits.join(", ")) : pass("C7:" + type, `file hygiene '${type}': no hand-made CSS/DOM/timers`);
        } catch (e) { rec("C7:" + type, `igiene file '${type}'`, "SKIP", String(e.message || e)); }
        if (info.debt.length) rec("C8:" + type, `debito '${type}'`, "PASS", info.debt.join("; "));
    }
}
