// ============================================================
// SurvivalKit/shields/smart-cache.js — D-213: SmartCache, the browser half (replaces the hand-written value split of D-211)
// ------------------------------------------------------------
// Just before a Run leaves (api.queuePrompt) the "pure" nodes of the prompt go to /succy/cache/precompute: the Python runs the
// REAL nodes and answers with each used output, written down exactly. lib/smart-cache-apply.js then feeds every such wire through
// a hidden Succy_Value: same value = same constant = ComfyUI keeps the branch after it, foreign nodes too (KSampler, loaders...).
// Every doubt (no server, slow answer, an error) = the prompt goes as it was: slower, never wrong. The workflow is never touched.
// It also keeps the "nothing changed" watch: two identical prompts in a row, and the nodes that still ran the second time.
// She checks the guest list twice: whoever shows up uninvited gets his name written down.
// ============================================================
import { api } from "../../../../scripts/api.js";
import { request, apply } from "../../lib/smart-cache-apply.js";

const TIMEOUT_MS = 1500;                   // the precompute answers in a few ms; past this the Run leaves as it was
const POLICY_TTL = 30000;                  // policies change only with a restart of ComfyUI: asked again every 30 s at most
const STATS = { runs: 0, asked: 0, twins: 0, rewired: 0, routed: 0, bypassed: 0, kept: 0, skipped: 0, errors: 0, last: "", ms: 0, wrapped: false };
let POL = null, polAt = 0, polErr = "", server = null;
const SENT = new Map();                    // prompt_id -> {fp, output}: what went out (last few)
let watch = null, lastFp = null, same = null;

async function stats_() {
    const r = await fetch("/succy/cache/stats");
    if (!r.ok) throw new Error("HTTP " + r.status);
    return r.json();
}

/** The policies from the server ({class_type: {policy, off, ...}}), cached; null = no server side (nothing is precomputed). */
async function policies(force = false) {
    const now = Date.now();
    if (!force && POL && now - polAt < POLICY_TTL) return POL;
    try { const j = await stats_(); server = j; POL = j?.policies || {}; polErr = ""; }
    catch (e) { polErr = String(e?.message || e); if (!POL) POL = null; }
    polAt = now;
    return POL;
}

async function transform(output) {
    const pol = await policies();
    if (!pol) return output;
    const req = request(output, (t) => (pol[t]?.policy === "pure" || pol[t]?.policy === "route") && !pol[t]?.off);
    if (!Object.keys(req.want).length) return output;
    STATS.asked++;
    const ctl = new AbortController(), timer = setTimeout(() => ctl.abort(), TIMEOUT_MS);
    let answer;
    try {
        const r = await fetch("/succy/cache/precompute", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(req), signal: ctl.signal });
        if (!r.ok) throw new Error("HTTP " + r.status);
        answer = await r.json();
    } finally { clearTimeout(timer); }
    if (answer?.error) { STATS.errors++; STATS.last = "server: " + answer.error; }
    const res = apply(output, answer);
    STATS.twins += res.twins; STATS.rewired += res.rewired; STATS.routed += res.routed; STATS.kept += res.kept; STATS.bypassed += res.bypassed.length;
    // a switch nobody reads won't run: its node shows the choice it would have made (Any's ▶), as if it had
    for (const id of res.bypassed) {
        const ui = answer?.route_ui?.[id], n = ui && globalThis.app?.graph?.getNodeById?.(Number(id));
        if (n && typeof n.onExecuted === "function") { try { n.onExecuted(ui); } catch (_) { /* a label, never a Run */ } }
    }
    STATS.skipped += Object.keys(answer?.skipped || {}).length; STATS.ms = answer?.ms ?? 0;
    return res.output;
}

function install() {
    if (STATS.wrapped || typeof api?.queuePrompt !== "function") return;
    const orig = api.queuePrompt;
    const wrapped = async function (number, data, ...rest) {
        let out = data?.output;
        if (data && typeof data === "object" && out) {
            try { out = await transform(out); data = { ...data, output: out }; STATS.runs++; }
            catch (e) { STATS.errors++; STATS.last = String(e?.name === "AbortError" ? "precompute too slow (> " + TIMEOUT_MS + " ms)" : e?.message || e); }   // never block a Run
        }
        const res = await orig.call(this, number, data, ...rest);
        try {
            if (res?.prompt_id && out) {
                SENT.set(String(res.prompt_id), { fp: JSON.stringify(out), output: out });
                while (SENT.size > 4) SENT.delete(SENT.keys().next().value);
            }
        } catch (_) { /* the watch is a bonus: it never costs a Run */ }
        return res;
    };
    wrapped.__succySmartCache = true;
    api.queuePrompt = wrapped;
    STATS.wrapped = true;
    // ---- the "nothing changed" watch: same prompt twice in a row -> who ran the second time ----
    const pid = (e) => String(e?.detail?.prompt_id ?? "");
    api.addEventListener("execution_start", (e) => { watch = { pid: pid(e), ran: new Set() }; });
    api.addEventListener("executing", (e) => { const id = typeof e?.detail === "object" ? e?.detail?.node : e?.detail; if (watch && id != null) watch.ran.add(String(id)); });
    api.addEventListener("execution_success", (e) => {
        const sent = SENT.get(pid(e));
        if (!watch || !sent) { lastFp = null; return; }
        if (lastFp !== null && sent.fp === lastFp) {
            const reg = globalThis.LiteGraph?.registered_node_types || {};
            same = { at: Date.now(), ran: [...watch.ran].map((id) => {
                const t = sent.output[id]?.class_type || "?";
                return { id, type: t, ours: t.startsWith("Succy_"), policy: POL?.[t]?.policy ?? null, pack: reg[t]?.nodeData?.python_module || "" };
            }) };
        }
        lastFp = sent.fp; watch = null;
    });
    for (const ev of ["execution_error", "execution_interrupted"]) api.addEventListener(ev, () => { lastFp = null; watch = null; });
}

export const SmartCache = {
    version: "0.2.0",
    install,
    request, apply,
    installed: () => STATS.wrapped && api?.queuePrompt?.__succySmartCache === true,
    /** asks the server again (policies + Python counters); the Monitor calls it, the answer arrives on the next stats() */
    refresh: () => policies(true),
    /** pure=false stops the precompute everywhere; off / on = class names. The server keeps it until ComfyUI restarts. */
    async switch(b = {}) {
        const r = await fetch("/succy/cache/switch", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(b) });
        const j = await r.json(); await policies(true); return j;
    },
    stats: () => ({ ...STATS, policies: POL, polErr, server, same }),
};
