// ============================================================
// lib/killswitch.js — the big red button (and the frontend-age alarm)
// ------------------------------------------------------------
// ONE switch for the whole pack. When it's ON the nodes still exist (they are plain Python nodes, the server doesn't care),
// but the JS layer installs NOTHING: no prototype wrapping, no canvas hooks, no window listeners, no effects.
// The nodes fall back to ComfyUI's own widgets. It's the "my frontend update broke something and I need to work NOW" button.
//
//   SuccyKill.on()      then F5     -> pack UI layer off
//   SuccyKill.off()     then F5     -> back to normal
//   SuccyKill.status()              -> { killed, why, frontend, tested }
//   or open ComfyUI with  ?succy=off  in the address bar (that one is per visit, nothing is stored)
//
// The alarm: when the frontend is newer than the last version this pack was tested on, one loud line appears in the console.
// v0.1.0 — 2026-10-18
// ============================================================

export const TESTED_FRONTEND = "1.55.17";            // bump it when a new frontend has been run through selfTest + Monitor
const KEY = "succy:kill";

function why() {
    try { if (globalThis.__SUCCY_KILL__ === true) return "global flag"; } catch (_) {}
    try { if (new URLSearchParams(globalThis.location?.search ?? "").get("succy") === "off") return "?succy=off in the address"; } catch (_) {}
    try { if (globalThis.localStorage?.getItem(KEY) === "1") return "SuccyKill.on()"; } catch (_) {}
    return "";
}

const REASON = why();
export const KILLED = !!REASON;

function api() {
    return {
        on() { try { localStorage.setItem(KEY, "1"); } catch (e) { console.warn("[Succy Pack] could not store the switch:", e); } console.warn("[Succy Pack] kill switch ON — reload the page (F5)."); return "reload"; },
        off() { try { localStorage.removeItem(KEY); } catch (_) {} console.warn("[Succy Pack] kill switch OFF — reload the page (F5)."); return "reload"; },
        status() { return { killed: KILLED, why: REASON, frontend: globalThis.__succyFrontendVersion || "", tested: TESTED_FRONTEND }; },
    };
}

if (!globalThis.SuccyKill) globalThis.SuccyKill = api();
if (KILLED) console.warn(`[Succy Pack] KILL SWITCH IS ON (${REASON}): the pack installs no patches and its nodes use plain ComfyUI widgets. SuccyKill.off() + F5 to undo.`);
