// ============================================================
// SurvivalKit/persistence/quick-undo.js
// ------------------------------------------------------------
// Ctrl+Z / Ctrl+Y that only touch OUR hidden natives are put back IN PLACE (D-193).
// ComfyUI's undo reloads the whole graph (loadGraphData): every node is rebuilt, every view, picture and brush mask decoded
// again — 1-3 s for ONE brush stroke on a Stitch. Here the ChangeTracker's step is read first: when the only difference between
// now and the state it brings back is the natives and the saved state of kit nodes (widgets_values / widgets_values_named /
// succy_natives / succy_state), the widgets and the state get their old values on the living nodes and the node is told to refresh. Anything else (a node moved, a link,
// a visible widget, a subgraph) goes through ComfyUI's own reload, untouched.
// After an in-place step the graph is serialized again and compared with ComfyUI's own graphEqual: a mismatch = the
// full reload of the same state, so the history never drifts. Same steps, same queues — just no demolition.
// v0.2.0 — 2026-10-17 (history drift watcher) · v0.2.1: a size heal that fails says what ELSE parts the two (D-200)
// ============================================================

import { NodeState } from "../core/node-state.js";

const STATS = { installed: false, fast: 0, full: 0, fellBack: 0, why: "", lastMs: 0, lastFull: "", checked: 0, healed: 0, drift: 0, driftWhere: "", driftType: "" };
export const quickUndoStats = () => ({ ...STATS });

const same = (a, b) => a === b || JSON.stringify(a) === JSON.stringify(b);
const keysOf = (a, b) => new Set([...Object.keys(a || {}), ...Object.keys(b || {})]);
// the first place two states part ways ("nodes.3.widgets_values.14"), for the Monitor: a fallback always says where
const firstDiff = (a, b, path = "", depth = 0) => {
    if (same(a, b)) return "";
    if (depth > 5 || !a || !b || typeof a !== "object" || typeof b !== "object") return path || "(root)";
    for (const k of keysOf(a, b)) { if (k === "order") continue; const d = firstDiff(a[k], b[k], path ? `${path}.${k}` : k, depth + 1); if (d) return d; }
    return path;
};
const NODE_OK = new Set(["widgets_values", "widgets_values_named", "properties"]);

// the nodes to put back, or a reason why this step needs ComfyUI's full reload
function plan(cur, next, graph) {
    if (globalThis.SUCCY_QUICK_UNDO === false) return { why: "switched off (SUCCY_QUICK_UNDO = false)" };     // the escape hatch, from the console
    if (!cur || !next || !Array.isArray(cur.nodes) || !Array.isArray(next.nodes) || !graph) return { why: "no state" };
    const canvasGraph = globalThis.app?.canvas?.graph;
    if (canvasGraph && canvasGraph !== graph) return { why: "inside a subgraph" };
    for (const k of keysOf(cur, next)) {
        if (k === "nodes") continue;
        if (k === "extra") {                                              // the view's offset / zoom is not history (ComfyUI ignores it too)
            const a = { ...(cur.extra || {}) }, b = { ...(next.extra || {}) }; delete a.ds; delete b.ds;
            if (!same(a, b)) return { why: "extra" };
        } else if (!same(cur[k], next[k])) return { why: k };
    }
    if (cur.nodes.length !== next.nodes.length) return { why: "nodes added / removed" };
    const todo = [];
    for (let i = 0; i < cur.nodes.length; i++) {
        const a = cur.nodes[i], b = next.nodes[i];
        if (!a || !b || a.id !== b.id || a.type !== b.type) return { why: "node order" };
        let changed = false;
        for (const k of keysOf(a, b)) {
            if (k === "properties") continue;
            if (same(a[k], b[k])) continue;
            if (!NODE_OK.has(k)) return { why: `node ${b.id}: ${k}` };
            changed = true;
        }
        const pa = a.properties || {}, pb = b.properties || {};
        for (const k of keysOf(pa, pb)) {
            if (same(pa[k], pb[k])) continue;
            if (k !== "succy_natives" && k !== "succy_state") return { why: `node ${b.id}: property ${k}` };
            changed = true;
        }
        if (!changed) continue;
        const n = graph.getNodeById?.(b.id), config = n && NodeState.get(n, "config", null);
        if (!n || n.type !== b.type || !config || typeof n._succyFindWidget !== "function") return { why: `node ${b.id}: not a kit node` };
        const named = b.widgets_values_named;
        if (!named || typeof named !== "object") return { why: `node ${b.id}: no named values` };
        // a visible native is drawn by ComfyUI itself (Vue nodes keep their own copy): only its reload shows the old value
        const keep = new Set(config.keepVisible || []), was = a.widgets_values_named || {};
        for (const name of keysOf(was, named)) if (!same(was[name], named[name]) && (keep.has(name) || !n._succyFindWidget(name))) return { why: `node ${b.id}: ${name} is visible` };
        todo.push({ n, b, config, state: !same(pa.succy_state, pb.succy_state) });
    }
    return todo.length ? { todo } : { why: "nothing of ours changed" };
}

function apply(todo, kitState) {
    for (const { n, b, config, state } of todo) {
        for (const [name, v] of Object.entries(b.widgets_values_named)) {
            const w = n._succyFindWidget(name);
            if (w && v !== null && v !== undefined && w.value !== v) w.value = v;
        }
        n.properties = n.properties || {};
        if (b.properties?.succy_natives === undefined) delete n.properties.succy_natives;
        else n.properties.succy_natives = b.properties.succy_natives;
        const ctx = NodeState.get(n, "ctx", null);
        // the saved state (brush size, tool...: "ui" keys ride along with the next checkpoint) goes back as the node's restore
        const values = state ? kitState?.replace(n, b.properties?.succy_state) : null;
        if (state && !values) throw new Error(`node ${n.id}: its state could not be put back`);
        if (!ctx) continue;
        if (values) { try { config.onRestore(ctx, values); } catch (e) { console.warn(`[SurvivalKit/quickUndo] restore #${n.id}:`, e); } }
        // the node re-reads its natives now; the "undo" channel replays the after-undo fixes (zoom, veils...) like a rebuild would
        try { config.refreshFromNative(ctx); } catch (e) { console.warn(`[SurvivalKit/quickUndo] refresh #${n.id}:`, e); }
        if (config.channels?.includes("undo")) { try { config.onChannel(ctx, "undo", { inPlace: true }); } catch (_) {} }
    }
}

// History drift (the ghost step): ~1 s after an undo / redo, ComfyUI must NOT have recorded a step by itself (undo queue grown, redo queue
// wiped) and the tracker's state must still be the one we landed on. A node that rewrites itself after a reload (Multi Math's outputs...) trips it:
// the Monitor says WHICH node / key, so the fix goes to the right door. Ghosts don't pay rent; we evict them.
const DRIFT_MS = 1000;
function watchDrift(ct, landed, how) {
    const uq = ct.undoQueue?.length, rq = ct.redoQueue?.length;
    clearTimeout(ct.__succyDriftTimer);                     // fast Ctrl+Z, Ctrl+Z, Ctrl+Z: only the LAST step is judged (the others are her, not a ghost)
    ct.__succyDriftTimer = setTimeout(() => {
        try {
            STATS.checked++;
            const grew = ct.undoQueue?.length !== uq, wiped = ct.redoQueue?.length !== rq;
            const graph = globalThis.app?.rootGraph || globalThis.app?.graph, CT = ct.constructor;
            // the living graph vs the step the history thinks it is in (ComfyUI's own equality: the next checkState would record a ghost step if they part)
            const live = graph ? JSON.parse(JSON.stringify(graph.serialize())) : null;
            // a node added / removed meanwhile (her action, a test cleaning up) is not a ghost: a ghost is the SAME nodes saying
            // something else. Judge only when both hold the same node ids (D-200)
            const ids = (g) => (g?.nodes || []).map((n) => n.id).sort().join(",");
            if (live && Array.isArray(ct.activeState?.nodes) && !grew && !wiped && ids(live) !== ids(ct.activeState)) return;
            const apart = live && typeof CT.graphEqual === "function" && !CT.graphEqual(ct.activeState, live);
            // a node that hugs its content (Pick Combo, Multi Math...) comes back from a reload at ITS height, not the one the step remembers (she resized it,
            // an old workflow...): the only difference is a size → the history takes the living size, no ghost step, nothing for her to undo twice (D-194)
            let beyond = "";
            if (apart && !grew && !wiped && Array.isArray(ct.activeState?.nodes) && ct.activeState.nodes.length === live.nodes?.length) {
                const fixed = JSON.parse(JSON.stringify(ct.activeState));
                fixed.nodes.forEach((n, i) => { if (n.id === live.nodes[i].id && !same(n.size, live.nodes[i].size)) n.size = live.nodes[i].size; });
                if (CT.graphEqual(fixed, live)) { ct.activeState = fixed; STATS.healed++; return; }
                // the size alone was not it: name the OTHER difference too (the first one shown is often just the size)
                const b = firstDiff(fixed, live);
                if (b) { const at = (o) => b.split(".").reduce((x, k) => (x == null ? x : x[k]), o), show = (v) => String(JSON.stringify(v)).slice(0, 60); beyond = ` · beyond the size: ${b} (step ${show(at(fixed))} · live ${show(at(live))})`; }
                else beyond = " · beyond the size: nothing firstDiff sees (graphEqual disagrees: order / ds?)";
            }
            let where = (apart ? firstDiff(ct.activeState, live) : "") || firstDiff(landed, ct.activeState);
            if (where && apart) {                                    // the two values at that spot: what she pastes is what we need
                const at = (o) => where.split(".").reduce((x, k) => (x == null ? x : x[k]), o), show = (v) => String(JSON.stringify(v)).slice(0, 60);
                where += ` (step ${show(at(ct.activeState))} · live ${show(at(live))})`;
            }
            if (!grew && !wiped && !apart && !where) return;
            const m = where.match(/^nodes\.(\d+)/), node = m ? ct.activeState?.nodes?.[+m[1]] : null;
            STATS.drift++;
            STATS.driftType = node?.type || "";
            STATS.driftWhere = `${how}: ${grew ? "undo queue grew" : wiped ? "redo queue changed" : apart ? "graph differs from the step" : "state moved"} · ${node ? `#${node.id} ${node.type} ` : ""}${where || "(queues only)"}${beyond}`;
        } catch (e) { STATS.driftWhere = "check: " + (e?.message || e); }
    }, DRIFT_MS);
}

// patches ChangeTracker.updateState (the one door both undo() and redo() go through). Installed lazily: the class
// may appear after the kit (window.comfyAPI.changeTracker, or the live tracker's constructor)
export function installQuickUndo(getChangeTracker, kitState) {
    const tryInstall = () => {
        if (STATS.installed) return true;
        const CT = globalThis.comfyAPI?.changeTracker?.ChangeTracker || getChangeTracker?.()?.constructor;
        const proto = CT?.prototype;
        if (!proto || typeof proto.updateState !== "function" || typeof CT.graphEqual !== "function") return false;
        if (proto.__succyQuickUndo) { STATS.installed = true; return true; }
        const orig = proto.updateState;
        proto.updateState = async function (source, target) {
            const next = Array.isArray(source) ? source[source.length - 1] : null, cur = this.activeState;
            const graph = globalThis.app?.rootGraph || globalThis.app?.graph;
            let p;
            try { p = next ? plan(cur, next, graph) : { why: "empty queue" }; } catch (e) { p = { why: "plan: " + (e?.message || e) }; }
            if (!p.todo) {
                STATS.full++; STATS.lastFull = p.why;
                const r = await orig.apply(this, arguments);
                if (next) watchDrift(this, this.activeState, "full reload");
                return r;
            }
            const t0 = performance.now(), flag = "_restoringState" in this ? "_restoringState" : "restoringState";
            source.pop(); target.push(cur);
            this[flag] = true;
            let ok = false, why = "the graph differs after the in-place step";
            try {
                apply(p.todo, kitState);
                const now = JSON.parse(JSON.stringify(graph.serialize()));        // the same copy ComfyUI checks its states with (clone)
                ok = CT.graphEqual(next, now);
                if (!ok) why = "the graph differs after the in-place step: " + firstDiff(next, now);
                if (ok) { this.activeState = next; this.updateModified?.(cur); }
            } catch (e) {
                why = "apply: " + (e?.message || e);
            } finally { this[flag] = false; }
            if (ok) { STATS.fast++; STATS.lastMs = Math.round(performance.now() - t0); watchDrift(this, next, "in place"); return; }
            // the living graph did not come out as the saved step: ComfyUI's own reload of that same step (queues put back first)
            STATS.fellBack++; STATS.why = why;
            source.push(next); target.pop();
            const r = await orig.apply(this, arguments);
            watchDrift(this, this.activeState, "full reload");
            return r;
        };
        proto.__succyQuickUndo = true;
        STATS.installed = true;
        return true;
    };
    if (tryInstall() || typeof window === "undefined") return;
    // not there yet: try again at the first undo / redo key (before ComfyUI's own listener handles it) and on a short timer
    const onKey = (e) => { if ((e.ctrlKey || e.metaKey) && /^[zy]$/i.test(e.key || "") && tryInstall()) window.removeEventListener("keydown", onKey, true); };
    window.addEventListener("keydown", onKey, true);
    let tries = 0;
    const timer = setInterval(() => { if (tryInstall() || ++tries > 60) { clearInterval(timer); if (STATS.installed) window.removeEventListener("keydown", onKey, true); } }, 1000);
}
