// ============================================================
// Succy_Primitive.js — "the ultimate madafacca primitive", NodeStructure v0.3 (glue, D-149)
// Born small and undecided: a grid of kinds. Pick one (or drag her output onto any widget and she copies it)
// and she BECOMES that kind for good: its controls, its size, its outputs. No going back, darling.
// This file contains ONLY: spec (catalog pieces), state schema, the packed defaults and the little `live` recipes.
//   controls per kind ............ slider / segmented / textarea / select / field (kit pieces)
//   outputs that follow the kind . `shape_output` count variant (value · value2 · value3, labels per kind)
//   text boxes that stretch ...... they fill the region, the node corner drives it (follow_mask + height.bindWhen, like the Preview)
//   values ....................... packed into the hidden `data` widget (JSON), the Python reads that
//   seed ......................... the real `seed` widget + ComfyUI's own control_after_generate
// ============================================================
import { SurvivalKit } from "./SurvivalKit/survival-kit.js";
import { NodeStructure } from "./NodeStructure/index.js";
import { outLinks } from "./lib/slots.js";

const TYPE = "Succy_Primitive";
const PACK = "data";
const CTRL = "control_after_generate";
const NATIVES = [PACK, "seed", CTRL];
const BIG = Number.MAX_SAFE_INTEGER;
// past 6 decimals the step turns into "1e-7" and the slider reads it as a whole number: 6 is the ceiling
const MAX_DEC = 6;                 // past 2^53 the browser starts eating digits
const MAX_COMBO = 5000;                              // entries copied from a target dropdown
const TEXT_FORMATS = ["STRING", "INT", "FLOAT", "BOOLEAN", "LIST", "DICT", "ARRAY", "JSON", "COMBO"];
const SOCKET = { STRING: "STRING", INT: "INT", FLOAT: "FLOAT", BOOLEAN: "BOOLEAN", COMBO: "COMBO" };      // others -> "*"
const SIZE_KINDS = ["RESOLUTION", "IMAGE", "MASK", "LATENT"];

// the grid she shows when she is born (COMBO is not here: she only learns it from a wire)
const KINDS = [
    { kind: "INT", icon: "🔢", label: "Int" }, { kind: "FLOAT", icon: "〰️", label: "Float" }, { kind: "SEED", icon: "🎲", label: "Seed" },
    { kind: "BOOL", icon: "🔘", label: "Bool" }, { kind: "TEXT", icon: "🔤", label: "String" }, { kind: "MULTILINE", icon: "📜", label: "Multiline" },
    { kind: "LIST", icon: "📋", label: "List" }, { kind: "COLOR", icon: "🎨", label: "Color" }, { kind: "RESOLUTION", icon: "📐", label: "Resolution" },
    { kind: "IMAGE", icon: "🖼️", label: "Image" }, { kind: "MASK", icon: "🎭", label: "Mask" }, { kind: "LATENT", icon: "🌫️", label: "Latent" },
];
// name + icon of every kind (COMBO too): the grid buttons and the automatic title "Succy - 🔢Int"
const META = Object.fromEntries([...KINDS, { kind: "COMBO", icon: "📑", label: "Combo" }].map((k) => [k.kind, k]));
const DEFAULT_TITLE = "Succy - 💎Primitive";
// node width each kind wants (px); "" = the newborn grid (wide enough that nothing wraps: her height stays put)
const WIDTH = { "": 330, MULTILINE: 320, LIST: 300, IMAGE: 300, MASK: 300, LATENT: 300, RESOLUTION: 300, SEED: 280, COMBO: 280 };

// "Custom" + the usual suspects (SDXL buckets included)
const PRESETS = [
    ["512×512", 512, 512], ["768×768", 768, 768], ["1024×1024", 1024, 1024],
    ["896×1152 · 3:4", 896, 1152], ["832×1216 · 2:3", 832, 1216], ["768×1344 · 9:16", 768, 1344], ["640×1536 · 9:21", 640, 1536],
    ["1152×896 · 4:3", 1152, 896], ["1216×832 · 3:2", 1216, 832], ["1344×768 · 16:9", 1344, 768], ["1536×640 · 21:9", 1536, 640],
    ["1280×720 · HD", 1280, 720], ["1920×1080 · Full HD", 1920, 1080], ["1080×1920 · phone", 1080, 1920],
];
const PRESET_OPTS = [{ value: "custom", label: "Custom" }, ...PRESETS.map(([l]) => ({ value: l, label: l }))];

// virtual natives packed into `data` (same defaults as Succy_Utils/Succy_Primitive.py)
const VDEF = {
    kind: "", int_v: 0, float_v: 0, precise: false, decimals: 4, bool_v: true, text_v: "",
    ml_v: "", trim: true, ml_out: "STRING", combo_v: "", combo_opts: "[]", combo_type: "COMBO", list_v: "",
    color_v: "#ff4fa3ff", w: 1024, h: 1024, mult: 8, scale: 1, preset: "1024×1024", batch: 1, fill: "#000000",
    mask_v: 1, latent_family: "sd",
};

/* ---------- glue: read what she is ---------- */
const kindOf = (api) => String(api.native.get("kind") || "");
const is = (k) => (api) => kindOf(api) === k;
const isSize = (api) => SIZE_KINDS.includes(kindOf(api));
let _co = { raw: null, val: [] };
function comboOpts(api) {
    const raw = api.native.get("combo_opts");
    if (raw === _co.raw) return _co.val;
    let v = []; try { v = JSON.parse(raw || "[]"); } catch (_) { v = []; }
    _co = { raw, val: Array.isArray(v) ? v : [] };
    return _co.val;
}
const gcd = (a, b) => (b ? gcd(b, a % b) : a);
const sizeOf = (api) => [Math.max(1, Number(api.native.get("w")) || 1), Math.max(1, Number(api.native.get("h")) || 1)];
const presetFor = (w, h) => PRESETS.find((p) => p[1] === w && p[2] === h)?.[0] || "custom";
// the size that really comes out: W/H x Scale (not for a latent), snapped to the multiple — same maths as the Python _size()
function outSize(api) {
    const m = Math.max(1, Number(api.native.get("mult")) || 8);
    const k = kindOf(api) === "LATENT" ? 1 : Math.max(0.01, Math.min(16, Number(api.native.get("scale")) || 1));
    const snap = (v) => Math.max(m, Math.min(Math.floor(16384 / m) * m, Math.round(Math.max(1, Math.min(16384, v * k)) / m) * m));
    const [w, h] = sizeOf(api);
    return [snap(w), snap(h)];
}
const autoTitle = (kind) => (META[kind] ? `Succy - ${META[kind].icon}${META[kind].label}` : null);
// the title follows the kind ONLY while it is one of ours: a name she typed herself is never touched
function retitle(api, kind) {
    const n = api.liveNode?.() || api.node;
    if (!n) return;
    const def = n.constructor?.title || DEFAULT_TITLE;
    const ours = new Set([def, DEFAULT_TITLE, ...Object.keys(META).map(autoTitle)]);
    if (n.title && !ours.has(n.title)) return;
    n.title = autoTitle(kind) || def;
    n.setDirtyCanvas?.(true, true);
}

const live = {
    isNone: (api) => !kindOf(api),
    // Multiline / List: the node's corner stretches the text box (the region binds txtH, follow_mask writes it, like the Preview)
    isTxt: (api) => is("MULTILINE")(api) || is("LIST")(api),
    // the box FILLS the region (like the Preview's pane): no fixed px on it, so Vue lets the node shrink too.
    // fixed part = the region minus the box (node pixels, zoom-proof); first frame: a fair guess
    txtPlus: (api) => {
        const ta = api.el(is("MULTILINE")(api) ? "mlV" : "listV"), root = api.el("root");
        if (!ta || !root || !ta.offsetHeight || !root.offsetHeight) return 48;
        // scrollHeight: squeezed to the floor, the box overflows — still counted. A 1px wobble (rounding) keeps the old value
        const v = Math.max(0, root.scrollHeight - ta.offsetHeight), last = api.cache.get("txtPlus");
        if (typeof last === "number" && Math.abs(v - last) <= 1) return last;
        api.cache.set("txtPlus", v);
        return v;
    },
    fillH: (api) => (live.isTxt(api) ? "100%" : ""),
    fillFlex: (api) => (live.isTxt(api) ? "1 1 0" : ""),
    ...Object.fromEntries(["INT", "FLOAT", "SEED", "BOOL", "TEXT", "MULTILINE", "COMBO", "LIST", "COLOR", "IMAGE", "MASK", "LATENT"].map((k) => [`is${k}`, is(k)])),
    isSize,
    // outputs: wire names value / value2 / value3 stay put, the SHOWN name says what comes out
    outs: (api) => {
        const k = kindOf(api);
        switch (k) {
            case "INT": return [["value", "INT", "int"]];
            case "FLOAT": return [["value", "FLOAT", "float"]];
            case "SEED": return [["value", "INT", "seed"]];
            case "BOOL": return [["value", "BOOLEAN", "boolean"]];
            case "TEXT": return [["value", "STRING", "string"]];
            case "MULTILINE": { const f = String(api.native.get("ml_out") || "STRING").toUpperCase(); return [["value", SOCKET[f] || "*", f.toLowerCase()]]; }
            case "COMBO": return [["value", String(api.native.get("combo_type") || "COMBO"), "value"]];
            case "LIST": return [["value", "LIST", "list"], ["value2", "INT", "count"]];
            case "COLOR": return [["value", "STRING", "hex"]];
            case "RESOLUTION": return [["value", "INT", "width"], ["value2", "INT", "height"], ["value3", "FLOAT", "megapixels"]];
            case "IMAGE": return [["value", "IMAGE", "image"], ["value2", "INT", "width"], ["value3", "INT", "height"], ["value4", "FLOAT", "megapixels"]];
            case "MASK": return [["value", "MASK", "mask"], ["value2", "INT", "width"], ["value3", "INT", "height"], ["value4", "FLOAT", "megapixels"]];
            case "LATENT": return [["value", "LATENT", "latent"], ["value2", "INT", "width"], ["value3", "INT", "height"]];
            default: return [["value", "*", "output"]];
        }
    },
    floatStep: (api) => (api.native.get("precise") ? 10 ** -Math.max(1, Math.min(MAX_DEC, Number(api.native.get("decimals")) || 4)) : 0.01),
    comboOpts: (api) => comboOpts(api).map((v) => ({ value: v, label: String(v) })),
    listCount: (api) => { const n = String(api.native.get("list_v") || "").split("\n").filter((l) => l.trim()).length; return `${n} item${n === 1 ? "" : "s"}`; },
    lastSeed: (api) => { const s = api.state.get("lastSeed"); return s == null || s === "" ? "" : `Last run used ${s}`; },
    hasLast: (api) => { const s = api.state.get("lastSeed"); return s != null && s !== ""; },
    notLatent: (api) => kindOf(api) !== "LATENT",
    chosen: (api) => !!kindOf(api),
    sizeInfo: (api) => {
        const [w, h] = outSize(api), g = gcd(w, h) || 1;
        const lat = kindOf(api) === "LATENT" ? ` · latent ${Math.floor(w / 8)}×${Math.floor(h / 8)}` : "";
        return `${w} × ${h} · ${(w * h / 1e6).toFixed(2)} MP · ${w / g}:${h / g}${lat}`;
    },
    multStep: (api) => Math.max(1, Number(api.native.get("mult")) || 8),
};

/* ---------- becoming something ---------- */
function become(api, kind, init = {}) {
    if (kindOf(api)) return;                                       // she already chose: no going back
    api.native.set("kind", kind);
    for (const [k, v] of Object.entries(init)) api.native.set(k, v);
    // the hidden seed only rolls for a SEED; everyone else keeps it still (a rolling seed would re-run the node every Queue)
    api.native.set(CTRL, kind === "SEED" ? (init[CTRL] || "randomize") : "fixed");
    api.wantWidth("kind", WIDTH[kind] || null);
    retitle(api, kind);
    api.relayout();
}

// ↺ Back to primitive state: every value goes back to default, the outputs back to one "*"
function unbecome(api) {
    api.native.set(PACK, "");
    api.native.set(CTRL, "fixed");
    api.wantWidth("kind", WIDTH[""]);
    retitle(api, "");
    api.relayout();
}

// Drag her output onto a widget while she's still undecided: she reads the target and turns into it, value included.
function adapt(api) {
    const node = api.liveNode?.() || api.node, g = node?.graph;
    const l = outLinks(node, 0)[0];
    const tgt = l ? g?.getNodeById?.(l.target_id) : null;
    const inp = tgt?.inputs?.[l.target_slot];
    if (!inp) return;
    const wname = inp.widget?.name || inp.name;
    const w = (tgt.widgets || []).find((x) => x?.name === wname);
    const type = String(Array.isArray(inp.type) ? "COMBO" : inp.type || "").toUpperCase();
    const val = w?.value;
    const values = Array.isArray(w?.options?.values) ? w.options.values : null;
    if (values || type === "COMBO") {
        const list = (values || []).slice(0, MAX_COMBO).map((v) => (typeof v === "string" || typeof v === "number" ? v : String(v)));
        return become(api, "COMBO", { combo_opts: JSON.stringify(list), combo_v: val ?? list[0] ?? "", combo_type: Array.isArray(inp.type) ? "COMBO" : String(inp.type || "COMBO") });
    }
    if (type === "INT") {
        if (/seed/i.test(wname)) { api.native.set("seed", Math.max(0, Math.min(BIG, Math.floor(Number(val) || 0)))); return become(api, "SEED"); }
        return become(api, "INT", { int_v: Math.trunc(Number(val) || 0) });
    }
    if (type === "FLOAT") {
        const n = Number(val) || 0, dec = (String(n).split(".")[1] || "").length;
        return become(api, "FLOAT", { float_v: n, ...(dec > 2 ? { precise: true, decimals: Math.min(MAX_DEC, dec) } : {}) });
    }
    if (type === "BOOLEAN") return become(api, "BOOL", { bool_v: !!val });
    if (type === "STRING") return become(api, w?.options?.multiline || w?.type === "customtext" ? "MULTILINE" : "TEXT", w?.options?.multiline || w?.type === "customtext" ? { ml_v: String(val ?? "") } : { text_v: String(val ?? "") });
    if (["IMAGE", "MASK", "LATENT"].includes(type)) return become(api, type);
}

