// ============================================================
// Succy_Preview_Anything_&_Convert.js — NodeStructure v0.2 (kit-first)
// This file contains ONLY: spec (catalog pieces), the pieces' JSON config,
// state schema and "when". No CSS, DOM, canvas, graph logic: it all lives in the kit (see CATALOG.md).
// Shape-shifting outputs (text = 1 output, image = 4, video = output+frame(+audio), audio = 1): `shape_output` behavior (D-66),
// only the JSON here. Convert follows the input (D-196): an INT in = INT out, a MASK in = MASK out, a VIDEO in = VIDEO out.
// VIDEO / AUDIO: player in the pane + timeline_element in its own region (trim window, current frame), natives in seconds.
// D-205: an IMAGE batch can be a clip too (As clip: Auto = the Python decides from how the frames move, On, Off = gallery);
// a VIDEO with As clip Off = its frames as pictures. fps field (+ AUTO, + EXT chip) and an optional `audio` input.
// ============================================================
import { SurvivalKit } from "./SurvivalKit/survival-kit.js";
import { NodeStructure } from "./NodeStructure/index.js";
import { inWired } from "./lib/slots.js";

const TYPE = "Succy_Preview_Anything_&_Convert";
const IMAGE_TYPES = ["IMAGE", "MASK"];
const TEXT_TYPES = ["STRING", "INT", "FLOAT", "BOOLEAN", "LIST", "DICT", "ARRAY", "JSON", "COMBO"];
// clips: Convert To = the format (D-198). video.auto = as it came; after the first Run it shows the real one (video.mp4...)
const VIDEO_FORMATS = ["video.auto", "video.mp4", "video.webm", "video.mkv", "video.mov", "video.avi", "video.gif"];
const AUDIO_FORMATS = ["audio.wav", "audio.mp3", "audio.flac", "audio.ogg", "audio.m4a"];
const OUT_SOCKET_TYPE = { IMAGE: "IMAGE", MASK: "MASK", STRING: "STRING", INT: "INT", FLOAT: "FLOAT", BOOLEAN: "BOOLEAN",
    ...Object.fromEntries(VIDEO_FORMATS.map((f) => [f, "VIDEO"])), ...Object.fromEntries(AUDIO_FORMATS.map((f) => [f, "AUDIO"])) };   // others -> "*"
const NATIVES = ["preview", "output_type", "invert_mask", "trim_start", "trim_end", "current_time", "split_audio", "as_clip", "clip_fps", "fps_auto", "audio_gain"];
const TL_H = 125;            // the timeline under a clip (track + 3 rows of numbers): fixed, glued to the bottom of the box
const AUDIO_H = 84;          // audio: the waveform strip, fixed (only the width changes)
const CLIP_H = 30;           // one row of As clip / fps (batches and videos only): fixed
const MAX_TEXT = 200000;
const DEFAULT_W = 280;
// VHS (Video Helper Suite, D-203): its loaders send frames as an IMAGE batch; ours reads fps and sound from the loader itself
const VHS_LOADERS = ["VHS_LoadVideo", "VHS_LoadVideoPath", "VHS_LoadVideoFFmpeg", "VHS_LoadVideoFFmpegPath"];

/* ---------- glue: state <-> values ---------- */
let _pc = { raw: null, val: null };
function content(api) {
    const raw = api.state.get("content");
    if (typeof raw !== "string" || !raw) return null;
    if (_pc.raw === raw) return _pc.val;
    let v = null; try { v = JSON.parse(raw); } catch (_) {}
    _pc = { raw, val: v };
    return v;
}
const setContent = (api, c) => api.state.set("content", c ? JSON.stringify(c) : "");
const imageUrl = (c) => SurvivalKit.compat.viewUrl(c?.images?.[0]);       // /view URL: Survival compat
const fileUrl = (f) => (f ? SurvivalKit.compat.viewUrl(f) : "");
const isClip = (c) => c?.kind === "video" || c?.kind === "audio";
const asClip = (api) => { const v = String(api.native.get("as_clip") || "auto"); return ["auto", "clip", "images"].includes(v) ? v : "auto"; };
// a batch's gallery (D-205c): the frames are served one by one by the node's route, never written to disk
const galleryOf = (c) => (c?.kind === "image" && c.gallery?.key != null && Number(c.gallery.total) > 1 ? c.gallery : null);
const frameUrl = (g, i, side, download) => SurvivalKit.compat.apiUrl(`/succy/preview/frame?key=${encodeURIComponent(g.key)}&token=${encodeURIComponent(g.token)}&i=${i}&side=${side}` + (download ? "&download=1" : ""));
const galleryItems = (g) => Array.from({ length: Number(g.total) }, (_, i) => ({ t: frameUrl(g, i, 256), b: frameUrl(g, i, 1600) }));
// what the last Run used (clip): the fps and the output volume. Different from the fields = the next Run applies them
const lastMedia = (api) => { const c = content(api); return isClip(c) ? c.media || {} : null; };

/* ---------- spec ---------- */
// ONE single region: [92px command box] [8px FIXED separator] [pane] [timeline, clips only]. Region height = plus + bodyHeight,
// plus = 100 (+ the timeline under a clip); no space between widgets => no stretchy grey. With Preview Off only the fixed part
// remains. ONE region on purpose (D-196): with Vue Nodes two regions share the node's spare room, a hidden one included.
// Heights per mode: image / video / text = the node is free, only the picture / the text box grows ·
// audio = locked and compact (fixed strip), only the width changes.
const UI_H = 92, SEP_H = 8;
