// ============================================================
// SurvivalKit/debug/selftest.js
// ------------------------------------------------------------
// Usage (console, on an EMPTY workflow, fresh tab — we like a clean slate):
//     await SurvivalKit.selfTest()
//     await SurvivalKit.selfTest({ stress: false, slow: false })  // quicker
//     await SurvivalKit.selfTest({ force: true })                 // even if the workflow isn't empty: its nodes are left alone,
//                                                                 // counts become deltas, the canvas-idle checks become SKIP
//     await SurvivalKit.selfTest({ type: "Succy_Pick_Combo" })    // pick the guinea pig yourself
//
// Prints a PASS / FAIL / SKIP table and a SELFTEST_JSON line
// to paste to Claude. It won't touch the kit unless you call it.
//
// No dedicated test node: the guinea pig is a REAL pack node (first of PREFER that is defined, creatable and has
// native widgets + kit DOM widgets). Natives and state keys are read from the node itself; RAF / canvas tests
// hang a synthetic <canvas> on each node, so they test the kit and not what a given node happens to draw.
// v0.3.0 — 2026-10-16 (force no longer wipes the workflow: baselines instead of a clean slate)
// ============================================================

import { logger } from "../core/log.js";

const PREFER = ["Succy_Pick_Combo", "Succy_Multi_Math", "Succy_Multi_Parse", "Succy_Preview_Anything_&_Convert", "Succy_Label"];
let TYPE = null;                 // the guinea pig, chosen at the start of every run
const wait = (ms) => new Promise((r) => setTimeout(r, ms));

async function waitFor(fn, ms = 5000, step = 50) {
    const t0 = performance.now();
    while (performance.now() - t0 < ms) {
        try { if (fn()) return true; } catch (_) {}
        await wait(step);
    }
    return false;
}

export function installSelfTest(SK) {
    SK.selfTest = (opts) => runSelfTest(SK, opts);
}

async function runSelfTest(SK, opts = {}) {
    const app = globalThis.app;
    const LG = globalThis.LiteGraph;
    const NS = SK.NodeState;
    const results = [];

    if (!app?.graph || !LG) {
        console.error("[selfTest] app/LiteGraph not available");
        return "ABORT";
    }
    const rootNodes = () => (app.graph._nodes ?? app.graph.nodes ?? []);
    if (rootNodes().length > 0 && !opts.force) {
        console.warn("[selfTest] the workflow is not empty: open a new tab (+) or use { force: true }");
        return "ABORT: workflow not empty";
    }
    const PRE = new Set(rootNodes().map((n) => n.id));           // her nodes (force on a busy workflow): never touched
    if (PRE.size) console.warn(`[selfTest] workflow not empty: its ${PRE.size} nodes are left alone, counts are deltas; an empty tab is still the real test`);
    let B = { live: 0, reg: 0, st: 0, bus: 0, canv: 0, cache: 0 };   // what the workflow already holds, taken after the guinea pig is picked

    const rec = (test, status, detail = "") =>
        results.push({ test, result: status, detail: String(detail) });

    let aborted = false;
    async function step(name, fn) {
        if (aborted) return;
        try {
            const r = await fn();
            if (r && r.skip) rec(name, "SKIP", r.skip);
            else if (r && r.ok === true) rec(name, "PASS", r.detail ?? "");
            else rec(name, "FAIL", (r && r.detail) ?? "");
        } catch (e) {
            rec(name, "FAIL", "exception: " + (e?.message ?? e));
        }
    }

    // --- helpers ---
    const liveNodes = () => {
        const out = new Set();
        const visit = (g) => {
            for (const n of (g?._nodes ?? g?.nodes ?? [])) if (n?.type === TYPE) out.add(n);
        };
        visit(app.graph);
        const sgs = app.graph.subgraphs;
        if (sgs?.values) for (const s of sgs.values()) visit(s);
        return out;
    };
    const inv = () => {
        let live = liveNodes().size;
        let reg = SK.registry.size(TYPE);
        let st = SK.state._byKey.size;
        let bus = SK.bus.size;
        const timers = SK.state._flushTimers.size;
        live -= B.live; reg -= B.reg; st -= B.st; bus -= B.bus;
        const ok = live === reg && reg === st && st === bus && timers === 0;
        return { ok, live, reg, st, bus, timers,
            text: `live=${live} registry=${reg} state=${st} bus=${bus} timers=${timers}` };
    };
    const rm = (n) => { try { app.graph.remove(n); } catch (_) {} };
    const readyAll = (nodes) => nodes.every((n) => NS.get(n, "ready", false));
    const cleanup = async () => {
        for (const n of [...rootNodes()]) if (!PRE.has(n.id)) rm(n);
        await wait(700);
        dropProbes();
        if (PRE.size) B.canv = SK.perf.stats().activeCanvases;     // only her nodes are left: an undo reload may have changed theirs
    };
    const cfg = () => globalThis.__succyConfigs?.get(TYPE);
    const wval = (n, name) => n.widgets?.find((w) => w.name === name)?.value;

    // --- synthetic canvas: one per node, owned by the node's ctx so the kit releases it on removal / heal ---
    const probes = new Set();
    const attachProbe = (n) => {
        const ctx = NS.get(n, "ctx", null);
        if (!ctx) return null;
        const el = document.createElement("canvas");
        el.width = 40; el.height = 40;
        el.style.cssText = "position:fixed;left:0;top:0;width:40px;height:40px;pointer-events:none;opacity:.01";
        document.body.appendChild(el);
        probes.add(el);
        ctx.perf.acquireCanvas(el, { fps: 30, render: () => {} });
        return el;
    };
    const dropProbes = () => { for (const el of probes) el.remove(); probes.clear(); };

    // --- what can we poke on this node? read it from its own widgets ---
    const altValue = (w) => {
        const v = w.value, o = w.options ?? {};
        if (Array.isArray(o.values) && o.values.length >= 2) return o.values.find((x) => x !== v);        // combo: the other entry
        if (typeof v === "boolean") return !v;
        if (typeof v === "number") { const up = v + 1; return (typeof o.max !== "number" || up <= o.max) ? up : v - 1; }
        if (typeof v === "string" && !/^\s*[\[{]/.test(v)) return v + "~st";                              // not JSON: the node would reformat it
        return undefined;
    };
    const deriveNatives = (n) => {
        const rank = (v) => (typeof v === "string" ? 2 : 1);                                              // numbers / booleans / combos first
        return (n.widgets ?? [])
            .filter((w) => !w._succyKitDom && !String(w.name).startsWith("ns_"))
            .map((w) => ({ name: w.name, from: w.value, to: altValue(w) }))
            .filter((x) => x.to !== undefined && x.to !== x.from)
            .sort((a, b) => rank(a.from) - rank(b.from))
            .slice(0, 3);
    };
    const deriveState = () => {
        for (const [key, d] of Object.entries(cfg()?.state ?? {}))
            if (d && d.policy === "immediate" && typeof d.default === "boolean") return { key, to: !d.default };
        return null;
    };
    let SUBJ = null;                 // { natives, state, domN }
    const mk = (x = 0, y = 0) => {
        const n = LG.createNode(TYPE);
        n.pos = [x, y];
        app.graph.add(n);
        return n;
    };

    async function pickSubject() {
        const defs = globalThis.NodeStructure?.defs;
        const names = opts.type ? [opts.type] : [...PREFER, ...[...(defs?.keys?.() ?? [])].filter((t) => !PREFER.includes(t))];
        const tried = [];
        for (const t of names) {
            if (!LG.registered_node_types?.[t] || !globalThis.__succyConfigs?.get(t)) { tried.push(`${t}: not registered`); continue; }
            TYPE = t;
            const n = mk();
            const ready = await waitFor(() => readyAll([n]), 5000);
            const natives = ready ? deriveNatives(n) : [];
            const domN = ready ? n.widgets.filter((w) => w._succyKitDom).length : 0;
            rm(n);
            await wait(500);
            if (ready && natives.length && domN) { SUBJ = { natives, domN, state: deriveState() }; return true; }
            tried.push(`${t}: ready=${ready} natives=${natives.length} kitDom=${domN}`);
        }
        console.error("[selfTest] no usable guinea pig. Tried: " + tried.join(" | "));
        return false;
    }

    try {
        if (!(await pickSubject())) {
            rec("guinea pig: a real pack node with natives + kit DOM", "FAIL", "none usable (is the pack's JS loaded and the nodes in object_info?)");
            aborted = true;
        } else {
            await wait(700);
            const live = liveNodes().size;
            B = { live, reg: SK.registry.size(TYPE), st: SK.state._byKey.size, bus: SK.bus.size, canv: SK.perf.stats().activeCanvases, cache: SK.cache._store.size };
            rec("guinea pig", "PASS", `${TYPE} · natives=${SUBJ.natives.map((x) => x.name).join(",")} · kitDom=${SUBJ.domN} · state=${SUBJ.state?.key ?? "-"}`);
        }

        // 1. patches in place
        await step("kit: API patch presenti", () => {
            const miss = [];
            if (typeof SK.state.release !== "function") miss.push("state.release");
            if (typeof SK.state.sync !== "function") miss.push("state.sync");
            if (typeof SK.state.flushAll !== "function") miss.push("state.flushAll");
            if (typeof SK.perf.addFlushHook !== "function") miss.push("perf.addFlushHook");
            if (typeof SK.perf.raf.wake !== "function") miss.push("raf.wake");
            if (typeof SK.registry.byKey !== "function") miss.push("registry.byKey");
            if (typeof SK.heal?.releaseResources !== "function") miss.push("heal.releaseResources");
            if (!SK.compat) miss.push("compat");
            // The shield wraps LGraph.prototype, but the frontend may wrap it again on top (the chain stays intact), so we
            // ask the shield itself, not the prototype's flag; the convert / unpack steps below prove it works in practice.
            if (!SK.subgraphShield?._installed) miss.push("subgraph shield");
            return { ok: miss.length === 0, detail: miss.length ? "missing: " + miss.join(", ") : "ok" };
        });

        // D-207: a manual Run renews run_id only where the hold is on (with it off the cache must survive)
        await step("hold: run_id renewed only where the hold is on", () => {
            const h = SK.hold;
            if (typeof h?.renewsRunId !== "function") return { ok: false, detail: "hold.renewsRunId missing" };
            const cls = h.stats().classes[0];
            if (!cls) return { ok: true, detail: "no hold class installed (nothing to check)" };
            const fake = (v) => ({ comfyClass: cls, widgets: [{ name: "pause_flow", value: v }, { name: "hold", value: v }, { name: "run_id", value: "x" }] });
            const off = h.renewsRunId(fake(false)), on = h.renewsRunId(fake(true)), bare = h.renewsRunId({ comfyClass: cls, widgets: [] });
            return { ok: !off && on && bare, detail: `${cls}: off=${off} on=${on} no-widget=${bare}` };
        });

        await step("compat: ComfyUI version", () => {
            const v = SK.compat?.getComfyVersion?.();
            return { ok: !!v, detail: "version=" + (v || "(empty)") };
        });

        await step("log: silent with debug off, talks with debug on", async () => {
            const L = SK.log;
            const prev = L.enabled;
            const lg = logger("selftest");
            const calls = [];
            const orig = console.log;
            console.log = (...a) => {
                if (typeof a[0] === "string" && a[0].startsWith("[SurvivalKit")) calls.push(a[0]);
                orig.apply(console, a);
            };
            try {
                L.setEnabled(false);
                lg.log("selftest line (off)");
                const off = calls.length;
                const buffered = L.buffer(5).some((e) => e.ns === "selftest");             // silent, but the ring buffer still keeps it
                L.setEnabled(true);
                lg.log("selftest line (on)");
                const on = calls.length - off;
                return { ok: off === 0 && on === 1 && buffered, detail: `console lines with off=${off}, with on=${on}, buffered=${buffered}` };
            } finally {
                console.log = orig;
                L.setEnabled(prev);
            }
        });

        // 2. create/delete invariants
        await step("10 nodes created/deleted: invariants", async () => {
            const ns = [];
            for (let i = 0; i < 10; i++) ns.push(mk((i % 5) * 420, Math.floor(i / 5) * 520));
            await waitFor(() => readyAll(ns), 5000);
            await wait(600);
            const a = inv();
            for (const n of ns) rm(n);
            await wait(900);
            const b = inv();
            return { ok: a.ok && a.live === 10 && b.ok && b.live === 0,
                detail: `with 10: ${a.text} | after delete: ${b.text}` };
        });

        // 3. RAF stopped at 0 canvases
        await step("RAF stopped with 0 canvases", async () => {
            await wait(300);
            const f0 = SK.perf.stats().rafFrames;
            await wait(700);
            const d = SK.perf.stats().rafFrames - f0;
            if (B.canv) return { skip: `the open workflow keeps ${B.canv} canvas(es) alive: run in an empty tab` };
            return { ok: d <= 1 && SK.perf.stats().activeCanvases === 0, detail: `frames in 700ms: ${d}` };
        });

        // 4. RAF wake + single chain (synthetic canvas on the guinea pig)
        await step("RAF wake + single chain + canvas released on removal", async () => {
            const n = mk(0, 0);
            await waitFor(() => readyAll([n]), 5000);
            attachProbe(n);
            await wait(300);
            let native = 0, run = true;
            const loop = () => { native++; if (run) requestAnimationFrame(loop); };
            requestAnimationFrame(loop);
            const f0 = SK.perf.stats().rafFrames;
            await wait(1000);
            run = false;
            const kit = SK.perf.stats().rafFrames - f0;
            const canv = SK.perf.stats().activeCanvases;
            rm(n);
            await wait(500);
            const after = SK.perf.stats().activeCanvases;
            dropProbes();
            return { ok: kit > 5 && kit <= native * 1.15 + 3 && canv === 1 + B.canv && after === B.canv,
                detail: `kit=${kit} native=${native} canvases=${canv} after remove=${after}` };
        });

        // 5. persistence round-trip
        await step("persistence: serialize -> configure", async () => {
            const n = mk();
            await waitFor(() => readyAll([n]), 5000);
            const ctx = NS.get(n, "ctx", null);
            for (const x of SUBJ.natives) ctx.utils.setNative(x.name, x.to);
            if (SUBJ.state) ctx.state.set(SUBJ.state.key, SUBJ.state.to);
            await wait(500);
            const data = JSON.parse(JSON.stringify(n.serialize()));
            const m = LG.createNode(TYPE);
            m.configure(data);
            const ss = (() => { try { return JSON.parse(m.properties.succy_state); } catch (_) { return null; } })();
            const nativesBack = SUBJ.natives.every((x) => wval(m, x.name) === x.to);
            const strOk = ["succy_state", "succy_natives"].every((k) => m.properties[k] === undefined || typeof m.properties[k] === "string");
            const stateOk = !SUBJ.state || ss?.[SUBJ.state.key] === SUBJ.state.to;
            rm(n);
            await wait(500);
            return { ok: nativesBack && strOk && stateOk && typeof m.properties.succy_state === "string",
                detail: `natives=${SUBJ.natives.map((x) => x.name + "=" + JSON.stringify(wval(m, x.name))).join(" ")} state=${JSON.stringify(ss && SUBJ.state ? { [SUBJ.state.key]: ss[SUBJ.state.key] } : ss)}` };
        });

        // 6. legacy
        await step("legacy workflow (plain objects)", async () => {
            const n0 = mk();
            await waitFor(() => readyAll([n0]), 5000);
            const data = JSON.parse(JSON.stringify(n0.serialize()));
            rm(n0);
            await wait(400);
            const plainNatives = Object.fromEntries(SUBJ.natives.map((x) => [x.name, x.to]));
            const t = LG.createNode(TYPE);
            t.configure({ ...data, id: 9999, properties: { ...(data.properties ?? {}), succy_state: { collapsed: true }, succy_natives: plainNatives } });
            return { ok: typeof t.properties.succy_state === "string" && typeof t.properties.succy_natives === "string",
                detail: `types=${typeof t.properties.succy_state}/${typeof t.properties.succy_natives}` };
        });

        await step("configure: widgets_values_named beats the index", async () => {
            const n0 = mk();
            await waitFor(() => readyAll([n0]), 5000);
            const data = JSON.parse(JSON.stringify(n0.serialize()));
            rm(n0);
            await wait(400);
            const x = SUBJ.natives[0];
            const t = LG.createNode(TYPE);
            t.configure({ ...data, id: 9998, widgets_values_named: { [x.name]: x.to } });
            return { ok: wval(t, x.name) === x.to, detail: `${x.name}=${JSON.stringify(wval(t, x.name))} (wanted ${JSON.stringify(x.to)})` };
        });

        // D-191: a big native (a brush PNG) is saved ONCE — in widgets_values_named — and still comes back
        await step("big native saved once, restored", async () => {
            const n0 = mk();
            await waitFor(() => readyAll([n0]), 5000);
            const w = (n0.widgets || []).find((x) => typeof x.value === "string" && (SUBJ.natives || []).some((y) => y.name === x.name));
            if (!w) { rm(n0); await wait(300); return { ok: true, detail: "n/a: the subject has no text native" }; }
            const big = "data:image/png;base64," + "Q".repeat(20000);
            w.value = big;
            const data = JSON.parse(JSON.stringify(n0.serialize()));
            rm(n0);
            await wait(400);
            const copies = JSON.stringify(data).split(big).length - 1;
            const t = LG.createNode(TYPE);
            t.configure({ ...data, id: 9997 });
            const back = wval(t, w.name) === big;
            return { ok: copies === 1 && back, detail: `copies=${copies} (want 1) back=${back}` };
        });

        // 7. heal: widgets removed by third parties (+ idempotent onResize)
        await step("heal: widgets removed by third parties, clean rebuild", async () => {
            const n = mk(0, 0);
            await waitFor(() => readyAll([n]), 5000);
            attachProbe(n);
            await wait(300);
            const domN = () => n.widgets.filter((w) => w._succyKitDom).length;
            const kill = () => {
                for (let i = n.widgets.length - 1; i >= 0; i--) if (n.widgets[i]?._succyKitDom) n.widgets.splice(i, 1);
            };
            const healOnce = async () => {
                kill();
                SK.heal.heal(n, true, cfg());
                await waitFor(() => readyAll([n]) && domN() === SUBJ.domN, 4000);
                await wait(300);
                attachProbe(n);                                  // heal released the old canvas (that's the point): hang a fresh one
            };
            await healOnce();
            const kit1 = domN();
            await healOnce();
            const kit2 = domN();
            const i = inv();
            const act = SK.perf.stats().activeCanvases;          // 1 = the old canvas was released, nothing leaked
            // The wrapper lives on the prototype (lifecycle.js): we check that it's still there and working.
            const resizeOk = typeof n.onResize === "function";
            rm(n);
            await wait(600);
            dropProbes();
            return { ok: kit1 === SUBJ.domN && kit2 === SUBJ.domN && act === 1 + B.canv && i.ok && resizeOk,
                detail: `kitDom=${kit1}/${kit2} (want ${SUBJ.domN}) activeCanvases=${act} onResize=${resizeOk} | ${i.text}` };
        });

        // 8. addDOMWidget fails
        await step("heal: addDOMWidget returns null -> not 'ready', then recovers", async () => {
            // the warnings below are staged: tell the Governor so they don't show up as errors (D-200)
            globalThis.__succyExpectErrors = { until: Date.now() + 4000, re: /addDOMWidget (returned null|failed)|incomplet/ };
            const n = LG.createNode(TYPE);
            n.addDOMWidget = () => null;
            n.pos = [0, 0];
            app.graph.add(n);
            await wait(1200);
            const failedReady = NS.get(n, "ready", false);
            delete n.addDOMWidget;
            SK.heal.heal(n, true, cfg());
            const rec2 = await waitFor(() => NS.get(n, "ready", false), 4000);
            await wait(300);
            globalThis.__succyExpectErrors = null;
            rm(n);
            await wait(600);
            const i = inv();
            return { ok: failedReady === false && rec2 && i.ok,
                detail: `readyAfterFailure=${failedReady} recovered=${rec2} | ${i.text}` };
        });

        // 9. per-node resources
        await step("per-node resources: scoped RAF and cleanup", async () => {
            const a = mk(0, 0), b = mk(450, 0);
            await waitFor(() => readyAll([a, b]), 5000);
            const ca = NS.get(a, "ctx", null), cb = NS.get(b, "ctx", null);
            const base = SK.perf.raf._ticks.size;
            const rafs0 = NS.all(a).rafs.size, rez0 = NS.all(a).resizeEls.size;
            ca.perf.acquireRAF("t", () => {});
            cb.perf.acquireRAF("t", () => {});
            const two = SK.perf.raf._ticks.size - base;
            const probe = document.createElement("div");
            document.body.appendChild(probe);
            ca.perf.observeResize(probe, () => {});
            const tracked = NS.all(a).resizeEls.size === rez0 + 1 && NS.all(a).rafs.size === rafs0 + 1;
            rm(a);
            await wait(500);
            const one = SK.perf.raf._ticks.size - base;
            rm(b);
            await wait(500);
            const zero = SK.perf.raf._ticks.size - base;
            probe.remove();
            return { ok: two === 2 && one === 1 && zero === 0 && tracked,
                detail: `ticks with 2 nodes=${two}, after remove a=${one}, after remove b=${zero}, tracked=${tracked}` };
        });

        // 10. B4
        await step("B4: setNative -> scheduleChange", async () => {
            const n = mk();
            await waitFor(() => readyAll([n]), 5000);
            await wait(500);
            const f0 = SK.perf.change.flushes;
            const x = SUBJ.natives[0];
            NS.get(n, "ctx", null).utils.setNative(x.name, x.to);
            await wait(600);
            const d = SK.perf.change.flushes - f0;
            rm(n);
            await wait(500);
            return { ok: d >= 1, detail: `changeFlushes +${d} (${x.name})` };
        });

        // 10b. D-200: the undo checkpoint waits while a changed node is still reshaping (a probe says "busy" until released)
        await step("B4b: the checkpoint waits for a reshaping node", async () => {
            if (typeof SK.perf.addSettleProbe !== "function") return { ok: false, detail: "perf.addSettleProbe missing" };
            // one try; a page flush in the window (tab hidden = "the page is leaving", the photo now by design) spoils it: try again once
            const once = async () => {
                const n = mk();
                await waitFor(() => readyAll([n]), 5000);
                await wait(500);
                // the probe says "busy" until WE say stop, not for a fixed time: on a slow PC the debounce timer itself can fire
                // after 400 ms, and a timed probe had already gone quiet (the old flaky FAIL: photo 1, waits 0)
                let hold = true;
                const off = SK.perf.addSettleProbe((node) => node === n && hold);
                const c0 = SK.perf.change.checkpointFlushes, w0 = SK.perf.change.settleWaits, p0 = SK.perf.change.pageFlushes;
                const x = SUBJ.natives[0];
                NS.get(n, "ctx", null).utils.setNative(x.name, x.to);
                await waitFor(() => SK.perf.change.settleWaits - w0 >= 1, 1500);   // the checkpoint came, saw "busy" and waits
                const early = SK.perf.change.checkpointFlushes - c0;               // no photo while the node is still "reshaping"
                hold = false;
                await waitFor(() => SK.perf.change.checkpointFlushes - c0 >= 1, 1500);
                const late = SK.perf.change.checkpointFlushes - c0, waited = SK.perf.change.settleWaits - w0;
                const paged = SK.perf.change.pageFlushes - p0;
                off(); rm(n); await wait(400);
                return { early, late, waited, paged };
            };
            let r = await once(), tries = 1;
            if (r.paged) { r = await once(); tries++; }
            const probe = !!globalThis.NodeStructure?._internal?.settleProbeOn?.();
            return { ok: r.early === 0 && r.late >= 1 && r.waited >= 1 && probe,
                detail: `photo before the reshape ended: ${r.early} (want 0) · after: ${r.late} · waits ${r.waited} · builder probe ${probe ? "on" : "OFF"}`
                    + (r.paged || tries > 1 ? ` · page flushes ${r.paged} (tab hidden?) · tries ${tries}` : "") };
        });

        // 11. undo/redo with ChangeTracker
        await step("real undo/redo (ChangeTracker)", async () => {
            const ct = SK.compat.getChangeTracker?.();
            if (!ct || typeof ct.undo !== "function" || typeof ct.redo !== "function")
                return { skip: "ChangeTracker.undo/redo not available" };
            const ns = [mk(0, 0), mk(450, 0), mk(900, 0)];
            await waitFor(() => readyAll(ns), 5000);
            await wait(500);
            if (typeof ct.captureCanvasState === "function") await ct.captureCanvasState();
            else if (typeof ct.checkState === "function") await ct.checkState();
            for (const n of ns) rm(n);
            await wait(500);
            if (typeof ct.captureCanvasState === "function") await ct.captureCanvasState();
            else if (typeof ct.checkState === "function") await ct.checkState();
            // LiteGraph does one undo per action: 3 removals need 3 undos.
            // We keep undoing until all 3 come back or we run out of tries. Persistence pays off.
            let u = 0;
            while (liveNodes().size - B.live < 3 && u < 10) {
                await ct.undo();
                await wait(300);
                u++;
            }
            await wait(900);
            const a = inv();
            // Same thing, mirrored, for redo.
            let r = 0;
            while (liveNodes().size - B.live > 0 && r < 10) {
                await ct.redo();
                await wait(300);
                r++;
            }
            await wait(900);
            const b = inv();
            return { ok: a.live === 3 && a.ok && b.live === 0 && b.ok,
                detail: `undo calls=${u} redo calls=${r} | after undo: ${a.text} | after redo: ${b.text}` };
        });
        await cleanup();

        // 12. D-193: an undo step that only changes a hidden native is put back IN PLACE (same node object, no graph reload), both ways
        await step("quick undo: a native step in place", async () => {
            const ct = SK.compat.getChangeTracker?.(), q = SK.quickUndo?.stats, T = "Succy_Crop";
            if (!ct || typeof ct.undo !== "function" || !q) return { skip: "ChangeTracker / quickUndo not available" };
            if (!q().installed) return { ok: false, detail: "quickUndo not installed on the ChangeTracker" };
            // a Crop's box native: hidden, and it does not reshape the node (a native that adds outputs falls back to the full reload, by design)
            if (!LG.registered_node_types?.[T] || !globalThis.__succyConfigs?.get(T)) return { skip: `${T} not registered` };
            const n = LG.createNode(T); app.graph.add(n);
            await waitFor(() => readyAll([n]), 5000);
            await wait(500);
            const check = () => (typeof ct.captureCanvasState === "function" ? ct.captureCanvasState() : ct.checkState?.());
            check(); await wait(300);                                     // ComfyUI squashes a change made within 50 ms of a checkpoint
            const f0 = q().fast, from = wval(n, "x"), to = (Number(from) || 0) + 7;
            NS.get(n, "ctx", null).utils.setNative("x", to);
            await wait(700); check();
            await ct.undo(); await wait(200);
            const back = wval(n, "x"), same = app.graph.getNodeById(n.id) === n;
            await ct.redo(); await wait(200);
            const again = wval(n, "x"), fast = q().fast - f0, why = q().lastFull || q().why;
            rm(n);
            await wait(400);
            return { ok: back === from && again === to && same && fast === 2,
                detail: `x: undo ${JSON.stringify(back)} (want ${JSON.stringify(from)}), redo ${JSON.stringify(again)} · same node ${same} · in place ${fast}/2${fast < 2 ? ` (${why})` : ""}` };
        });
        await cleanup();

        // 12b. D-194: a native that RESHAPES the node (outputs / size) goes through ComfyUI's full reload; ~1 s after undo + redo the living graph must
        // still be the history's state, or ComfyUI records a ghost step by itself (the Monitor's "History drift")
        await step("quick undo: a reshaping native leaves no ghost step", async () => {
            const ct = SK.compat.getChangeTracker?.(), q = SK.quickUndo?.stats;
            if (!ct || typeof ct.undo !== "function" || !q || !q().installed) return { skip: "ChangeTracker / quickUndo not available" };
            const cases = [["Succy_Multi_Math", "num_equations"], ["Succy_Pick_Combo", "num_values"]].filter(([t]) => LG.registered_node_types?.[t] && globalThis.__succyConfigs?.get(t));
            if (!cases.length) return { skip: "no reshaping node registered" };
            const check = () => (typeof ct.captureCanvasState === "function" ? ct.captureCanvasState() : ct.checkState?.());
            const out = []; let bad = false;
            for (const [T, nat] of cases) {
                const n0 = LG.createNode(T); app.graph.add(n0);
                await waitFor(() => readyAll([n0]), 5000);
                await wait(500); check(); await wait(300);
                const d0 = q().drift, from = wval(n0, nat), to = (Number(from) || 1) + 1;
                // change it the way the node's own UI does: write AND let the node reshape (D-200). The bare utils.setNative only
                // writes: the node kept the old outputs / size, the history photographed a half node no UI can produce, and the
                // redo's rebuild "drifted" from it (the FAIL seen on her PC and, once the bench really ran it, in the bench too)
                const ui = globalThis.NodeStructure?.instanceOf?.(n0)?.api;
                if (ui?.native?.set) ui.native.set(nat, to);
                else { const ctx = NS.get(n0, "ctx", null); ctx.utils.setNative(nat, to); try { globalThis.__succyConfigs.get(T).refreshFromNative?.(ctx); } catch (_) {} }
                await wait(900); check();
                await ct.undo(); await wait(400); await ct.redo();
                await wait(1400);                                         // the watcher judges ~1 s after the LAST step
                const n1 = app.graph.getNodeById(n0.id), val = n1 ? wval(n1, nat) : null, drift = q().drift - d0;
                if (drift || val !== to) bad = true;
                out.push(`${T}.${nat}: ${val}/${to} · drift ${drift}${drift ? ` (${q().driftWhere})` : ""}`);
                rm(n1 || n0); await wait(400);
            }
            return { ok: !bad, detail: out.join(" | ") };
        });
        await cleanup();

        // 13. subgraph
        const sgApi = typeof app.graph.convertToSubgraph === "function" && typeof app.graph.unpackSubgraph === "function";
        await step("subgraph: convert + unpack", async () => {
            if (!sgApi) return { skip: "convertToSubgraph/unpackSubgraph not available" };
            const ns = [mk(0, 0), mk(450, 0)];
            await waitFor(() => readyAll(ns), 5000);
            const r = app.graph.convertToSubgraph(new Set(ns));
            const sgNode = r?.node;
            if (!sgNode) return { skip: "convertToSubgraph did not return the node" };
            await wait(900);
            const a = inv();
            app.graph.unpackSubgraph(sgNode);
            await wait(1000);
            const back = [...liveNodes()];
            await waitFor(() => readyAll(back), 4000);
            const b = inv();
            return { ok: a.live === 2 && a.ok && b.live === 2 && b.ok && readyAll(back),
                detail: `inside: ${a.text} | after unpack: ${b.text} ready=${readyAll(back)}` };
        });
        await cleanup();

        await step("nested subgraph, 2 levels", async () => {
            if (!sgApi) return { skip: "subgraph API not available" };
            const ns = [mk(0, 0), mk(450, 0)];
            await waitFor(() => readyAll(ns), 5000);
            const r1 = app.graph.convertToSubgraph(new Set(ns));
            if (!r1?.node) return { skip: "first convert failed" };
            await wait(800);
            const r2 = app.graph.convertToSubgraph(new Set([r1.node]));
            if (!r2?.node) return { skip: "second convert failed" };
            await wait(900);
            const a = inv();
            app.graph.unpackSubgraph(r2.node);
            await wait(900);
            const mid = rootNodes().find((x) => !PRE.has(x.id) && (x.subgraph || x.type?.length > 20));
            if (mid) app.graph.unpackSubgraph(mid);
            await wait(1000);
            const back = [...liveNodes()];
            await waitFor(() => readyAll(back), 4000);
            const b = inv();
            return { ok: a.live === 2 && a.ok && b.live === 2 && b.ok && readyAll(back),
                detail: `nested: ${a.text} | after 2 unpacks: ${b.text} ready=${readyAll(back)}` };
        });
        await cleanup();

        // 14. stress 50 — let's see how much it can take
        if (opts.stress !== false) {
            await step("stress: 50 nodes", async () => {
                const ns = [];
                for (let i = 0; i < 50; i++) ns.push(mk((i % 10) * 420, Math.floor(i / 10) * 520));
                const rdy = await waitFor(() => readyAll(ns), 15000);
                for (const n of ns) attachProbe(n);
                await wait(1500);
                const a = inv();
                const canv = SK.perf.stats().activeCanvases;
                for (const n of ns) rm(n);
                await wait(2000);
                const b = inv();
                const f0 = SK.perf.stats().rafFrames;
                await wait(600);
                const idle = SK.perf.stats().rafFrames - f0;
                return { ok: rdy && a.live === 50 && a.ok && canv === 50 + B.canv && b.live === 0 && b.ok && (idle <= 1 || B.canv > 0),
                    detail: `ready=${rdy} canvas=${canv} | with 50: ${a.text} | after: ${b.text} | idle frames=${idle}` };
            });
        }

        // 15. cache cleaned up (slow)
        if (opts.slow !== false) {
            await step("cache cleaned ~5s after removal", async () => {
                await cleanup();
                await wait(5800);
                const size = SK.cache._store.size;
                return { ok: size <= B.cache, detail: `leftover buckets=${size - B.cache}` };
            });
        }
    } finally {
        await cleanup();
    }

    const pass = results.filter((r) => r.result === "PASS").length;
    const fail = results.filter((r) => r.result === "FAIL").length;
    const skip = results.filter((r) => r.result === "SKIP").length;
    console.table(results);
    console.log(`[selfTest] PASS=${pass} FAIL=${fail} SKIP=${skip}`);
    console.log("SELFTEST_JSON " + JSON.stringify(results));
    return `PASS=${pass} FAIL=${fail} SKIP=${skip}`;
}
