// ============================================================
// NodeStructure/runtime/live-link.js — the LIVE LINK (D-156): what a Succy node outputs "as it is now" reaches the Succy nodes on
// its wires without a Queue. ONE flag on the Python side opts a node in (SUCCY_LIVE + succy_live on its class); this file:
//   types()            the opted-in node types and their live outputs (/succy/live/types, asked once)
//   specOf(node)       the node as it is now + the live nodes behind its wires: { node_id, type, widgets, linked, from: {input: {output, ...}} }
//                      — the chain the Python's live_eval runs from the far end. fromOf(node) = just its `from` (for routes that POST a node).
//   sourceOf(node, input)  { node, output } when a live node feeds that input, else null
//   view(spec, output) the output, reduced (/succy/live/view): { ready, src, width, height, info } or { ready: false, need, why }.
//                      Fetched only when the chain changed (its signature), shared by every viewer of the same chain.
//                      { ready: true, empty: true } = the source chose to hand out NOTHING (an Any on Index 0): as good as no wire (D-172)
//   remember / stateFor  what a consumer last got for one of its inputs (live_system writes, ready_system / peek_system read)
// Full size never travels here: Run, Copy and Download ask the Python with the same chain. Succubus was here — she's already
// wearing what you picked, before you even asked her out.
// ============================================================
import { ShotFeed } from "./shot-feed.js";

const KP = () => globalThis.SurvivalKit?.nodePorts;
const A = () => globalThis.app?.api;
const DEPTH = 8;
const subs = new Set();
const STATS = { fetches: 0, failed: 0, hits: 0, last: "" };
let types = null, asking = null;

const fnv = (u) => { let x = 0x811c9dc5; for (let i = 0; i < u.length; i++) x = Math.imul(x ^ u.charCodeAt(i), 16777619); return (x >>> 0).toString(36); };
const publish = () => { for (const fn of [...subs]) { try { fn(); } catch (e) { console.warn("[NodeStructure] live-link subscriber:", e); } } };

function ask() {
    if (types || asking || !A()) return;
    asking = A().fetchApi("/succy/live/types").then((r) => (r.ok ? r.json() : { types: {} })).catch(() => ({ types: {} }))
        .then((j) => { types = j && typeof j.types === "object" && j.types ? j.types : {}; asking = null; publish(); });
}

const outName = (node, slot) => String(node?.outputs?.[slot]?.name ?? "");

function sourceOf(node, input) {
    ask();
    if (!types) return null;
    const s = KP()?.inputNode?.(node, input);
    if (!s?.node) return null;
    const output = outName(s.node, s.slot), outs = types[s.node.type];
    return Array.isArray(outs) && outs.includes(output) ? { node: s.node, output } : null;
}

// the node as it is now, with the live nodes behind its wires (a node seen twice in one chain stops there: no loops)
function specOf(node, depth = 0, seen = new Set()) {
    const snap = KP()?.snapshot?.(node);
    if (!snap) return null;
    const spec = { node_id: snap.id, type: snap.type, widgets: snap.widgets, linked: snap.linked, from: {} };
    if (depth >= DEPTH || seen.has(node)) return spec;
    seen.add(node);
    for (const input of snap.linked) {
        const src = sourceOf(node, input);
        if (!src || seen.has(src.node)) continue;
        const up = specOf(src.node, depth + 1, seen);
        if (up) spec.from[input] = { ...up, output: src.output };
    }
    seen.delete(node);
    return spec;
}

// the chain's signature: every value in it + the last Run of every node in it (a Run changes what it says)
function sigOf(spec, node) {
    if (!spec) return "none";
    const runs = [];
    const walk = (s, n) => {
        runs.push(ShotFeed.get(n)?.v ?? "");
        for (const [input, up] of Object.entries(s.from || {})) walk(up, sourceOf(n, input)?.node);
    };
    walk(spec, node);
    return fnv(JSON.stringify(spec)) + ":" + runs.join(",");
}

// one fetch per (chain, output, size), the latest few kept
const VIEWS = new Map();
const VIEWS_MAX = 24;
function view(spec, output, max = 1536, sig = "") {
    const key = `${sig || fnv(JSON.stringify(spec))}|${output}|${max}`;
    const hit = VIEWS.get(key);
    if (hit) { STATS.hits++; VIEWS.delete(key); VIEWS.set(key, hit); return hit; }
    STATS.fetches++;
    const p = A().fetchApi(`/succy/live/view?output=${encodeURIComponent(output)}&max=${max}`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(spec) })
        .then(async (r) => {
            let j = {};
            try { j = await r.json(); } catch (_) { /* not json */ }
            if (!r.ok) return { ready: false, need: "error", why: j.error || `HTTP ${r.status}` };
            if (!j.ready) return { ready: false, need: j.need || "run", why: j.why || "not ready" };
            return { ready: true, src: j.data || "", empty: !!j.empty, width: Number(j.width) || 0, height: Number(j.height) || 0, info: j.info || null };
        })
        .catch((e) => { STATS.failed++; STATS.last = String(e?.message || e); return { ready: false, need: "error", why: STATS.last }; });
    VIEWS.set(key, p);
    p.then((v) => { if (!v.ready) VIEWS.delete(key); });          // a "not yet" is not worth remembering either (D-168): the file may land a beat after the widget says its name
    while (VIEWS.size > VIEWS_MAX) VIEWS.delete(VIEWS.keys().next().value);
    return p;
}

// what each consumer input last got: "<graph>:<node>:<input>" -> { state: live | loading | wait, src, width, height, info, why, sig }
const STATES = new Map();
const STATES_MAX = 96;
const skey = (node, input) => `${node?.graph?.id ?? "g"}:${node?.id ?? "?"}:${input}`;

export const LiveLink = {
    types() { ask(); return types || {}; },
    sourceOf, specOf, sigOf, view,
    fromOf(node) { return specOf(node)?.from || {}; },
    subscribe(fn) { ask(); subs.add(fn); return () => subs.delete(fn); },
    remember(node, input, st) { const k = skey(node, input); STATES.delete(k); STATES.set(k, st); while (STATES.size > STATES_MAX) STATES.delete(STATES.keys().next().value); },
    // null = no live node on that wire (the old rules apply)
    stateFor(node, input) { return sourceOf(node, input) ? STATES.get(skey(node, input)) || { state: "loading" } : null; },
    // a node's own output as it is now (live_system `self`): null until asked
    selfState(node, key) { return STATES.get(skey(node, key)) || null; },
    isLiveType(type) { ask(); return !!types && Array.isArray(types[type]); },
    stats() { return { types: types ? Object.keys(types).length : null, views: VIEWS.size, consumers: STATES.size, subs: subs.size, ...STATS }; },
};
