// ============================================================
// NodeStructure/components/timeline.js — timeline_element (D-196)
//   The trim bar under a clip: [▶] [track: kept window, two handles, playhead, faint waveform]
//   and below it Start / End / Current, each as seconds AND frame (frames only with fps > 0).
//   All three numbers are linked: change the time and the frame follows (and back), via fps.
//   Bound refs (writable, e.g. $native.trim_start) hold SECONDS: start, end (0 = up to the end), current.
//   Same sums as the Python (trim_window / frame_range / frame_at): frame = round(t·fps) for the edges,
//   End frame shown INCLUSIVE (the last frame kept), current = the frame on screen at that time.
//   Current ALWAYS sits inside the kept window (D-198): trim past it and it moves along. Typed values are clamped to
//   what is allowed (no 11 s in a 10.005 s clip). ‹ › and the arrow keys move one frame (audio: 10 ms).
//   Rows: Start green, End red, Current yellow (the handles and the playhead wear the same colours).
//   Drags and playback stay local; the refs are written once, when the gesture ends (one undo step, no ghosts).
//   The player is the pane_box named in `pane` (paneMedia): play loops inside the window, like an editor.
// ============================================================
import { mkEl, num } from "./index.js";
import { makeSlider } from "./controls.js";
import { paneMedia } from "../pieces/panes.js";
import { piece } from "../catalog/registry.js";
import { C, ex, N, R, ID } from "../catalog/kit.js";
import { parseRef } from "../core/parser.js";
import { writeRef } from "../core/binding.js";

const LIVE = new Set();             // mounted timelines (Monitor: how many, how many playing, how many without a player)
const EPS = 1e-6;

// pure sums, exported for the selfTest: seconds <-> frames and the window rules
export const tlMath = {
    step: (fps) => (fps > 0 ? 1 / fps : 0.001),
    // window: start in [0, dur - step], end in [start + step, dur]; snapped to the frame grid when there is one.
    // current in [start, end - step]: the last frame kept at most (audio: 1 ms before the end)
    norm(v, dur, fps) {
        const st = tlMath.step(fps), snap = (t) => (fps > 0 ? Math.round(t * fps) / fps : Math.round(t * 1000) / 1000);
        let s = snap(Math.min(Math.max(0, v.s), Math.max(0, dur - st)));
        let e = snap(Math.min(Math.max(v.e, s + st), dur));
        if (e - s < st - EPS) { e = Math.min(dur, s + st); s = Math.max(0, e - st); }
        const cc = Math.min(Math.max(s, v.c), Math.max(s, e - st));
        // half a millisecond of slack: a time typed / stepped to the ms lands on the frame it means, not the one before
        const c = fps > 0 ? Math.min(Math.max(s, Math.floor((cc + 0.0005) * fps + EPS) / fps), Math.max(s, e - st)) : Math.round(cc * 1000) / 1000;
        return { s, e, c };
    },
    // what each field may hold right now (seconds; frames with fps): typing / arrows / drag can't leave it
    limits(k, v, dur, fps) {
        const st = tlMath.step(fps);
        const sec = k === "s" ? [0, Math.max(0, v.e - st)] : k === "e" ? [Math.min(dur, v.s + st), dur] : [v.s, Math.max(v.s, v.e - st)];
        if (!(fps > 0)) return { sec, fr: null };
        const f = tlMath.frames(v, fps);
        const fr = k === "s" ? [0, f.e] : k === "e" ? [f.s, Math.max(f.s, Math.round(dur * fps) - 1)] : [f.s, f.e];
        return { sec, fr };
    },
    frames: (v, fps) => ({ s: Math.round(v.s * fps), e: Math.round(v.e * fps) - 1, c: Math.floor(v.c * fps + EPS) }),
    // a frame typed by hand -> seconds (End is inclusive: its edge sits one frame later)
    fromFrame: (which, f, fps) => (which === "e" ? (f + 1) / fps : f / fps),
    // stored end: 0 = "up to the end" (so a longer clip later still plays whole)
    endOut: (e, dur) => (e >= dur - EPS ? 0 : e),
    endIn: (raw, dur) => (raw > 0 && raw <= dur ? raw : dur),
};

piece(C("timeline_element", {
    scopo: "Trim bar for a clip: kept window with two handles, playhead, play/loop, Start/End/Current as seconds and frames.",
    natura: "works", dominio: "ui", estado: "draft", archetipo: "trigger", tag: ["media", "video", "audio", "time", "control"],
    uses: ["slider_element"],
    props: {
        start: R("writable ref with the window start (s)"), end: R("writable ref with the window end (s, 0 = up to the end)"),
        current: R("writable ref with the current time (s): the frame that goes out"),
        duration: R("clip length (s)"), fps: R("frames per second (0 = no frames: audio)"), frames: R("frame count (default round(duration·fps))"),
        peaks: R("waveform bars 0..1 drawn faintly in the track"), pane: ID("id of the pane_box that plays the clip"),
        height: N("track height (px)", 26),
    },
    css: `
.ns-tl{display:flex;flex-direction:column;gap:5px;min-width:0;user-select:none}
.ns-tl-bar{display:flex;flex-direction:row;gap:6px;align-items:center;min-width:0}
.ns-tl-play{flex:0 0 28px;height:26px;padding:0;border:1px solid var(--ns-border);border-radius:4px;background:var(--ns-bg-2);color:var(--ns-c-text-3, #aaa);font:bold 12px monospace;cursor:pointer}
.ns-tl-play:hover{color:var(--ns-t-info)}.ns-tl-play.ns-on-info{color:var(--ns-t-info);border-color:color-mix(in srgb,var(--ns-t-info) 55%,transparent)}
.ns-tl-play:disabled{opacity:.35;cursor:default}
.ns-tl-track{position:relative;flex:1 1 0;min-width:40px;height:26px;background:var(--ns-c-pane-bg, #0e0e0e);border:1px solid var(--ns-border);border-radius:4px;overflow:hidden;cursor:pointer;touch-action:none;outline:none}
.ns-tl-track:focus-visible{border-color:var(--ns-c-accent, #4a9eff)}
.ns-tl-wave{position:absolute;inset:0;width:100%;height:100%;opacity:.45;pointer-events:none}
.ns-tl-sel{position:absolute;top:0;bottom:0;background:color-mix(in srgb,var(--ns-t-info) 22%,transparent);border-left:2px solid var(--ns-t-info);border-right:2px solid var(--ns-t-info);box-sizing:border-box;pointer-events:none}
.ns-tl-out{position:absolute;top:0;bottom:0;background:rgba(0,0,0,.45);pointer-events:none}
.ns-tl-h{position:absolute;top:0;bottom:0;width:8px;margin-left:-4px;cursor:ew-resize}
.ns-tl-h::after{content:"";position:absolute;left:2px;right:2px;top:7px;bottom:7px;border-radius:2px;background:var(--ns-tl-k)}
.ns-tl-ph{position:absolute;top:0;bottom:0;width:2px;margin-left:-1px;background:var(--ns-tl-k);pointer-events:none;box-shadow:0 0 4px rgba(0,0,0,.6)}
.ns-tl-ks{--ns-tl-k:#3ddc84}.ns-tl-ke{--ns-tl-k:#e05a5a}.ns-tl-kc{--ns-tl-k:#e8c547}
.ns-tl-grid .ns-slider.ns-tl-ks,.ns-tl-grid .ns-slider.ns-tl-ke,.ns-tl-grid .ns-slider.ns-tl-kc{background:color-mix(in srgb,var(--ns-tl-k) 13%,var(--ns-bg-2, #1a1a1a));border-color:color-mix(in srgb,var(--ns-tl-k) 45%,transparent)}
.ns-tl-grid .ns-tl-ks .ns-slider-fill,.ns-tl-grid .ns-tl-ke .ns-slider-fill,.ns-tl-grid .ns-tl-kc .ns-slider-fill{background:color-mix(in srgb,var(--ns-tl-k) 26%,transparent);border-right-color:var(--ns-tl-k)}
.ns-tl-lab.ns-tl-ks,.ns-tl-lab.ns-tl-ke,.ns-tl-lab.ns-tl-kc{color:var(--ns-tl-k)}
.ns-tl-grid .ns-slider-arr{opacity:.55}.ns-tl-grid .ns-slider-arr:hover{opacity:1;color:var(--ns-tl-k, #fff)}
.ns-tl-grid{display:grid;grid-template-columns:56px 1fr 1fr;gap:4px 6px;align-items:center;min-width:0}
.ns-tl-grid.ns-tl-nofps{grid-template-columns:56px 1fr}
.ns-tl-grid .ns-slider{height:22px;min-width:0}
.ns-tl-grid .ns-slider-val{font-size:11px}
.ns-tl-lab{font:10px monospace;letter-spacing:.6px;text-transform:uppercase;color:var(--ns-c-text-3, #aaa);white-space:nowrap}
.ns-tl-head{font:9px monospace;letter-spacing:.8px;text-transform:uppercase;color:var(--ns-c-text-4, #666);text-align:center}
`,
    esempio: ex({ t: "timeline_element", start: "$cache.a", end: "$cache.b", current: "$cache.c", duration: 10, fps: 24 }),
}), (node, h) => {
    const { rt } = h;
    const el = mkEl("div", "ns-tl");
    const bar = mkEl("div", "ns-tl-bar");
    const play = mkEl("button", "ns-tl-play"); play.type = "button"; play.textContent = "▶"; play.title = "Play the kept window (loops) · Space";
    const track = mkEl("div", "ns-tl-track"); track.tabIndex = 0;
    track.title = "Drag the blue handles to trim · click / drag to move the current frame · double click = keep everything · ← → one frame";
    const wave = mkEl("canvas", "ns-tl-wave");
    const outL = mkEl("div", "ns-tl-out"), outR = mkEl("div", "ns-tl-out"), sel = mkEl("div", "ns-tl-sel");
    const hs = mkEl("div", "ns-tl-h ns-tl-ks"), he = mkEl("div", "ns-tl-h ns-tl-ke"), ph = mkEl("div", "ns-tl-ph ns-tl-kc");
    track.append(wave, outL, outR, sel, hs, he, ph);
    bar.append(play, track);
    const grid = mkEl("div", "ns-tl-grid");
    el.append(bar, grid);

    // ---- model: seconds from the refs, a local override while a gesture is running ----
    const refs = { s: parseRef(node.start || ""), e: parseRef(node.end || ""), c: parseRef(node.current || "") };
    const dur = () => Math.max(0, num(h, node.duration, 0));
    const fps = () => Math.max(0, num(h, node.fps, 0));
    const nFrames = () => { const f = num(h, node.frames, 0); return f > 0 ? Math.round(f) : Math.max(1, Math.round(dur() * fps())); };
    let local = null;                                      // { s, e, c } while dragging / playing / typing live
    const stored = () => tlMath.norm({ s: num(h, node.start, 0), e: tlMath.endIn(num(h, node.end, 0), dur()), c: num(h, node.current, 0) }, dur(), fps());
    const model = () => local || stored();
    const commit = (v) => {
        const d = dur(), cur = stored(), nv = tlMath.norm(v, d, fps());
        local = null;
        if (Math.abs(nv.s - cur.s) > EPS) writeRef(rt, refs.s, nv.s);
        if (Math.abs(nv.e - cur.e) > EPS) writeRef(rt, refs.e, tlMath.endOut(nv.e, d));
        if (Math.abs(nv.c - cur.c) > EPS) writeRef(rt, refs.c, nv.c);
        paint();
    };
    const preview = (v) => { local = tlMath.norm(v, dur(), fps()); paint(); };

    // ---- the player (pane_box) ----
    const media = () => (node.pane ? paneMedia(h.tree.els.get(node.pane) || rt.el?.(node.pane)) : null);     // the pane may live in another region
    const bound = new WeakSet();
    let raf = 0, playing = false;
    const seek = (t) => { const m = media(); if (m && m.readyState >= 1 && Math.abs((m.currentTime || 0) - t) > 1 / Math.max(48, fps() * 2)) { try { m.currentTime = t; } catch (_) {} } };
    const tick = () => {
        raf = 0;
        const m = media();
        if (!playing || !m || rt.destroyed) return;
        const v = local || stored();
        let t = m.currentTime || 0;
        if (t >= v.e - EPS || t < v.s - 0.05) { t = v.s; try { m.currentTime = t; } catch (_) {} }
        local = { ...v, c: t };
        paint(true);
        raf = requestAnimationFrame(tick);
    };
    const stop = (keep = true) => {
        if (raf) { cancelAnimationFrame(raf); raf = 0; }
        const m = media();
        const was = playing; playing = false;
        if (m && !m.paused) { try { m.pause(); } catch (_) {} }
        if (was && keep && m) commit({ ...(local || stored()), c: m.currentTime || 0 }); else if (was) { local = null; paint(); }
    };
    const start = () => {
        const m = media(); if (!m) return;
        const v = stored();
        if (v.c < v.s - EPS || v.c >= v.e - tlMath.step(fps())) { try { m.currentTime = v.s; } catch (_) {} }
        else seek(v.c);
        playing = true;
        const p = m.play(); if (p?.catch) p.catch(() => { playing = false; paint(); });
        if (!raf) raf = requestAnimationFrame(tick);
        paint();
    };
    const bind = (m) => {
        if (!m || bound.has(m)) return;
        bound.add(m);
        h.listen(m, "loadedmetadata", () => { if (!playing) seek(stored().c); });
        h.listen(m, "ended", () => { if (playing) { try { m.currentTime = (local || stored()).s; m.play(); } catch (_) {} } });
        h.listen(m, "pause", () => { if (playing && !m.ended) stop(true); });
    };
    h.listen(play, "pointerdown", (e) => e.stopPropagation());
    h.listen(play, "click", (e) => { e.stopPropagation(); if (playing) stop(true); else start(); });

    // ---- track: handles, playhead, double click ----
    const tAt = (x) => { const r = track.getBoundingClientRect(); return Math.min(1, Math.max(0, (x - r.left) / (r.width || 1))) * dur(); };
    h.listen(track, "pointerdown", (e) => {
        if (e.button !== 0 || dur() <= 0) return;
        e.preventDefault(); e.stopPropagation();
        try { track.focus({ preventScroll: true }); } catch (_) { /* not focusable right now */ }
        if (playing) stop(true);
        const r = track.getBoundingClientRect(), d = dur(), v0 = stored();
        const px = (t) => r.left + (t / (d || 1)) * r.width;
        const ds = Math.abs(e.clientX - px(v0.s)), de = Math.abs(e.clientX - px(v0.e));
        const what = Math.min(ds, de) <= 7 ? (ds <= de ? "s" : "e") : "c";
        const id = e.pointerId;
        const at = (x) => {
            const t = tAt(x), v = { ...(local || v0) };
            v[what] = what === "e" && fps() > 0 ? Math.round(t * fps()) / fps() : t;
            preview(v);
            seek(what === "e" ? Math.max(0, local.e - tlMath.step(fps())) : local[what]);
        };
        at(e.clientX);
        const move = (m) => { if (m.pointerId !== id) return; m.preventDefault(); m.stopImmediatePropagation(); at(m.clientX); };
        const end = (m) => {
            if (m.pointerId !== id) return;
            window.removeEventListener("pointermove", move, true); window.removeEventListener("pointerup", end, true); window.removeEventListener("pointercancel", end, true);
            const v = local || v0;
            commit(v);
            seek(stored().c);
        };
        window.addEventListener("pointermove", move, true); window.addEventListener("pointerup", end, true); window.addEventListener("pointercancel", end, true);
    });
    h.listen(track, "dblclick", (e) => { e.preventDefault(); e.stopPropagation(); commit({ ...stored(), s: 0, e: dur() }); });
    h.listen(track, "keydown", (e) => {
        const st = tlMath.step(fps());
        if (e.key === " ") { e.preventDefault(); e.stopPropagation(); if (playing) stop(true); else start(); }
        else if (e.key === "ArrowLeft" || e.key === "ArrowRight") {
            e.preventDefault(); e.stopPropagation();
            const v = stored(); commit({ ...v, c: v.c + (e.key === "ArrowLeft" ? -1 : 1) * st * (e.shiftKey ? 10 : 1) + (fps() > 0 ? EPS : 0) });
            seek(stored().c);
        }
    });
    for (const ev of ["keyup", "keypress"]) h.listen(track, ev, (e) => e.stopPropagation());

    // ---- the number rows: seconds (3 decimals) and frames, linked ----
    const fields = {};
    const head = (t) => { const x = mkEl("span", "ns-tl-head"); x.textContent = t; return x; };
    const hdT = head("seconds"), hdF = head("frame");
    grid.append(mkEl("span"), hdT, hdF);
    for (const [k, label] of [["s", "Start"], ["e", "End"], ["c", "Current"]]) {
        const lab = mkEl("span", "ns-tl-lab ns-tl-k" + k); lab.textContent = label;
        // the bar spans the whole clip (so it reads like the track); min / max = what this field may hold right now
        const ts = makeSlider(h, () => { const L = tlMath.limits(k, model(), dur(), fps()).sec; return { min: L[0], max: L[1], step: 0.001, lo: 0, top: dur() || 1, int: false, arrow: fps() > 0 ? 1 / fps() : 0.01 }; });
        const fs = makeSlider(h, () => { const L = tlMath.limits(k, model(), dur(), fps()).fr || [0, 0]; const top = Math.max(0, nFrames() - 1); return { min: L[0], max: L[1], step: 1, lo: 0, top: top || 1, int: true }; });
        ts.el.classList.add("ns-tl-k" + k); fs.el.classList.add("ns-tl-k" + k);
        ts.onCommit((mode) => {
            const v = { ...model(), [k]: ts.get() };
            if (mode === "live") { preview(v); seek(k === "e" ? Math.max(0, local.e - tlMath.step(fps())) : local[k]); } else { commit(v); seek(stored().c); }
        });
        fs.onCommit((mode) => {
            const v = { ...model(), [k]: tlMath.fromFrame(k, fs.get(), fps() || 1) + (k === "c" ? EPS : 0) };
            if (mode === "live") { preview(v); seek(k === "e" ? Math.max(0, local.e - tlMath.step(fps())) : local[k]); } else { commit(v); seek(stored().c); }
        });
        grid.append(lab, ts.el, fs.el);
        fields[k] = { ts, fs };
    }

    // ---- paint ----
    let lastWave = "";
    const drawWave = () => {
        const pk = h.val(node.peaks); const list = Array.isArray(pk) ? pk : [];
        const w = Math.max(1, Math.round(track.clientWidth)), hh = Math.max(1, Math.round(track.clientHeight));
        const sig = list.length + ":" + (list[0] ?? "") + ":" + (list[list.length - 1] ?? "") + ":" + w + "x" + hh;
        if (sig === lastWave) return;
        lastWave = sig;
        wave.width = w; wave.height = hh;
        const g = wave.getContext("2d"); if (!g) return;
        g.clearRect(0, 0, w, hh);
        if (!list.length) return;
        g.fillStyle = getComputedStyle(el).getPropertyValue("--ns-t-info").trim() || "#4a9eff";
        const bw = w / list.length;
        for (let i = 0; i < list.length; i++) { const v = Math.max(0.02, Math.min(1, Number(list[i]) || 0)) * (hh / 2 - 1); g.fillRect(i * bw, hh / 2 - v, Math.max(1, bw - 0.4), v * 2); }
    };
    const pct = (t) => (dur() > 0 ? (t / dur()) * 100 : 0) + "%";
    function paint(fromTick = false) {
        const d = dur(), f = fps(), v = model();
        bind(media());
        const m = media();
        play.disabled = !m || d <= 0;
        play.textContent = playing ? "❚❚" : "▶";
        play.classList.toggle("ns-on-info", playing);
        sel.style.left = pct(v.s); sel.style.width = (d > 0 ? ((v.e - v.s) / d) * 100 : 0) + "%";
        outL.style.left = "0"; outL.style.width = pct(v.s);
        outR.style.left = pct(v.e); outR.style.right = "0";
        hs.style.left = pct(v.s); he.style.left = pct(v.e); ph.style.left = pct(v.c);
        grid.classList.toggle("ns-tl-nofps", !(f > 0));
        hdF.hidden = !(f > 0);
        const fr = f > 0 ? tlMath.frames(v, f) : null;
        for (const k of ["s", "e", "c"]) {
            const { ts, fs } = fields[k];
            if (Math.abs(ts.get() - v[k]) > EPS) ts.set(v[k]); else ts.paint();
            fs.el.style.display = f > 0 ? "" : "none";      // .ns-slider is display:flex: `hidden` alone would not hide it
            if (fr && fs.get() !== fr[k]) fs.set(fr[k]); else fs.paint();
        }
        if (!fromTick) { drawWave(); if (!playing && !local) seek(v.c); }
    }
    const inst = { rt, playing: () => playing, hasMedia: () => !!media(), shown: () => el.isConnected && el.offsetHeight > 0 };
    LIVE.add(inst);
    h.bag.add(() => { LIVE.delete(inst); if (raf) cancelAnimationFrame(raf); raf = 0; playing = false; });
    try { const ro = new ResizeObserver(() => drawWave()); ro.observe(track); h.bag.add(() => ro.disconnect(), "observers"); } catch (_) { /* the wave redraws on the next update */ }
    paint();
    return { el, update: () => { if (!playing) paint(); }, handlesText: true };
});

export const timelineStats = () => {
    const all = [...LIVE].filter((t) => !t.rt.destroyed);
    const shown = all.filter((t) => t.shown());
    return { timelines: all.length, shown: shown.length, playing: all.filter((t) => t.playing()).length, noPlayer: shown.filter((t) => !t.hasMedia()).length };
};
