// ============================================================
// NodeStructure/components/ready.js — how READY each picture input of a node is, and a veil that says what is missing (D-143)
//   ready_system   (io) one state per declared input, "as it is now":
//                    ready   = loaded here, or its source already has the picture
//                    run     = wired, but the picture gets here only with a Run
//                    empty   = wired to a node that has no picture yet
//                    none    = no source at all (no wire, no file)
//                    covered = no source of its own, another input brings it (a Crop on `stitch` brings base + mask)
//                    blind   = wired, the data exists only inside the Run (the live view can't see it)
//                    wait    = wired to a LIVE Succy node (D-156) that can't say yet (its own words: "the Load has no picture");
//                              a live node that answers counts as ready, whatever the probe says
//                  -> { inputs: {name: {state, from, text}}, missing: [text], ready, sig }. Re-reads itself every 400 ms, redraws on change.
//   wait_element  over a view_box: nothing when all is ready; otherwise the picture under it stays but dimmed (or black when there is
//                  none) and a card lists EXACTLY what is missing. With `block` the view under it is off (no brush, drag, menu);
//                  a drop / paste still gets through, so the missing picture can land right there.
// The node declares its inputs in config.ready_system.inputs. Succubus was here — she won't start until everyone has arrived.
// ============================================================
import { mkEl } from "./index.js";
import { piece } from "../catalog/registry.js";
import { C, ex, S, R, B } from "../catalog/kit.js";
import { ShotFeed } from "../runtime/shot-feed.js";
import { inWiredByName } from "../../lib/slots.js";
import { LiveLink } from "../runtime/live-link.js";

const KP = () => globalThis.SurvivalKit?.nodePorts;
const nameOf = (n) => `${String(n?.title || n?.type || "node").trim()} #${n?.id ?? "?"}`;
const labelOf = (d) => d.label || String(d.input).replace(/_/g, " ");
// what the user reads, one line per input that holds the view back
const TEXT = {
    none: (l) => `${l}: no source — load it (📂), drop / paste it here, or wire it`,
    run: (l, f) => `${l}: needs a Run so ${f} sends it`,
    empty: (l, f) => `${l}: wired to ${f}, which has no picture yet`,
    blind: (l, f, h) => `${l}: comes from ${f} — ${h || "only the Run sees it (load a file to preview it)"}`,
    wait: (l, f, h, why) => `${l}: ${why || `${f} has nothing to send yet`}`,
};

// config ready_system.inputs: [{ input, label?, file?, probe: "source" | "self" | "blind", cover?, optional?, hint? }]
//   optional = it never holds the view back: its line goes to `note` instead of `missing` (a wired mask the Crop only sees at Run)
//   hint     = replaces the tail of the "blind" line
//   file  = the native holding a picture loaded on THIS node for that input (it counts as ready)
//   probe = where the picture shows up: "source" = the node on the wire looks at it (shot feed) · "self" = this node got it (shot feed,
//           after a Run or a drop) · "blind" = nowhere before the Run
//   cover = another input (or a list: all of them) that brings this one when it has no source of its own
const readyOf = (api) => {
    const me = api.liveNode?.() || api.node;
    const list = Array.isArray(api.cfg?.("ready_system")?.inputs) ? api.cfg("ready_system").inputs : [];
    const inputs = {}, missing = [], notes = [], sig = [];
    for (const d of list) {
        if (!d?.input) continue;
        const l = labelOf(d), wired = inWiredByName(me, d.input);
        const file = d.file ? String(api.native?.get?.(d.file) || "") : "";
        // cover = one input, or a list that must ALL be there (wired, or loaded on the node): `stitch` is covered by base_image + mask
        const has = (name) => inWiredByName(me, name) || !!String(api.native?.get?.((list.find((x) => x?.input === name) || {}).file || "") || "");
        const covered = !!d.cover && (Array.isArray(d.cover) ? d.cover.length > 0 && d.cover.every((c) => has(c)) : inWiredByName(me, d.cover));
        let state, from = "";
        if (!wired) state = file ? "ready" : covered ? "covered" : "none";
        else {
            const src = KP()?.inputNode?.(me, d.input)?.node || null;
            from = nameOf(src);
            const lv = LiveLink.stateFor(me, d.input);
            if (lv) state = lv.state === "wait" ? "wait" : "ready";
            else if (d.probe === "self") state = file || ShotFeed.get(me)?.src ? "ready" : "run";
            else if (d.probe === "blind") state = file || covered ? "ready" : "blind";
            else if (ShotFeed.get(src)?.src) state = "ready";
            else state = (KP()?.snapshot?.(src)?.linked?.length) ? "run" : "empty";
        }
        const why = state === "wait" ? LiveLink.stateFor(me, d.input)?.why || "" : "";
        const text = d.optional && state !== "blind" && state !== "wait" ? "" : TEXT[state]?.(l, from, d.hint, why) || "";
        inputs[d.input] = { state, from, text };
        if (text) (d.optional ? notes : missing).push(text);
        sig.push(`${d.input}:${state}:${from}:${why}`);
    }
    return { inputs, missing, note: notes.join(" · "), ready: missing.length === 0, sig: sig.join("|") };
};
readyOf.ensure = (api) => {
    let last = "";
    api.onDispose(ShotFeed.subscribe(() => api.refresh()));
    api.every(() => {
        const n = api.liveNode?.() || api.node;
        if (n?.flags?.collapsed) return;
        const s = readyOf(api).sig;
        if (s !== last) { last = s; api.refresh(); }
    }, 400);
};
piece(C("ready_system", {
    scopo: "How ready each picture input is NOW (ready / run / empty / none / covered / blind) and the list of what is missing.",
    natura: "works", dominio: "runtime", estado: "draft", tag: ["graph", "state", "input", "preview"], props: {},
    esempio: ex({ t: "label_element", text: "{{$live.ready_system.ready}}" }),
}), readyOf);

// ---------- wait_element (the veil) ----------
const CSS = `
.ns-ready-anchor{display:none}
.ns-ready{position:absolute;inset:0;display:grid;place-items:center;padding:12px;pointer-events:none;z-index:1}
.ns-ready[hidden]{display:none}
.ns-ready.ns-ready-dim{background:rgba(11,11,13,.62)}
.ns-ready.ns-ready-black{background:#000}
.ns-ready.ns-ready-inline{position:static;padding:4px 0}
.ns-ready.ns-ready-block{pointer-events:auto;cursor:not-allowed}
.ns-ready.ns-ready-inline.ns-ready-black,.ns-ready.ns-ready-inline.ns-ready-dim{background:none}
.ns-ready-card{max-width:92%;padding:8px 12px;border-radius:6px;background:rgba(0,0,0,.72);border:1px solid color-mix(in srgb,var(--ns-t-warn,#e0a040) 60%,transparent);font:11px/1.5 ui-monospace,Consolas,monospace;color:#ddd}
.ns-ready-card b{display:block;margin-bottom:3px;color:var(--ns-t-warn,#e0a040);letter-spacing:.5px;text-transform:uppercase;font-size:10px}
.ns-ready-card div::before{content:"• ";color:var(--ns-t-warn,#e0a040)}
`;
piece(C("wait_element", {
    scopo: "Veil over a view_box listing the missing inputs: picture dimmed under it, black when there is none.",
    natura: "works", dominio: "ui", estado: "draft", archetipo: "leaf",
    tag: ["preview", "state", "input", "overlay"], uses: ["ready_system", "view_box"], css: CSS,
    props: {
        ready: R("the readiness (ref, e.g. $live.ready_system): needs {missing}"),
        picture: R("what the view shows under the veil (ref, e.g. its src): empty = black background"),
        title: S("title of the card", "Waiting for"),
        show: R("false (ref) = the veil stays off whatever is missing (default: on) (D-147)"),
        block: B("true = while it shows, the view under it is off: no brush, no drag, no right-click menu (a drop / paste still gets through, D-144)", false),
    },
    esempio: ex({ t: "view_box", children: [{ t: "wait_element", ready: { missing: ["replacement: needs a Run"] } }] }),
}), (node, h) => {
    const el = mkEl("div", "ns-ready-anchor");
    const ov = mkEl("div", "ns-ready"), card = mkEl("div", "ns-ready-card");
    ov.append(card); ov.hidden = true;
    if (node.block) {
        ov.classList.add("ns-ready-block");
        const eat = (e) => { e.stopPropagation(); if (e.type === "contextmenu") e.preventDefault(); };
        for (const ev of ["pointerdown", "pointermove", "pointerup", "click", "dblclick", "contextmenu"]) ov.addEventListener(ev, eat);
    }
    h.bag.add(() => ov.remove());
    let host = null, last = "";
    const update = () => {
        // the veil lives on the VIEW (not the zoomed stage), under its buttons; outside a view it sits inline
        const root = el.closest(".ns-view");
        if (root && host !== root) { host = root; root.insertBefore(ov, root.querySelector(".ns-view-hud")); ov.classList.remove("ns-ready-inline"); }
        else if (!root && !host && el.parentElement) { host = el.parentElement; host.insertBefore(ov, el.nextSibling); ov.classList.add("ns-ready-inline"); }
        const r = h.val(node.ready) || {}, miss = Array.isArray(r.missing) ? r.missing : [];
        const pic = !!String(h.val(node.picture) || "");
        const on = node.show === undefined || !!h.val(node.show);
        const key = miss.join("\n") + "|" + pic + "|" + on;
        if (key === last) return;
        last = key;
        ov.hidden = !miss.length || !on;
        ov.classList.toggle("ns-ready-dim", pic);
        ov.classList.toggle("ns-ready-black", !pic);
        card.replaceChildren();
        const t = mkEl("b"); t.textContent = String(h.val(node.title) || "Waiting for"); card.append(t);
        for (const m of miss) { const d = mkEl("div"); d.textContent = m; card.append(d); }
        ov.title = miss.join("\n");
    };
    queueMicrotask(update); setTimeout(update, 50); setTimeout(update, 400);
    return { el, update, handlesText: true };
});
