// ============================================================
// SurvivalKit/compat/banner.js — frontend-age alarm
// ------------------------------------------------------------
// One console line when the running frontend is newer than the last one this pack was tested on (killswitch.js: TESTED_FRONTEND).
// It also remembers the version on globalThis.__succyFrontendVersion for SuccyKill.status() and the Monitor.
// v0.1.0 — 2026-10-18
// ============================================================
import { app } from "../../../../scripts/app.js";
import { TESTED_FRONTEND, KILLED } from "../../lib/killswitch.js";
import { compareVersion, parseVersion } from "../../lib/version.js";
import { getComfyVersion } from "./version.js";

let announced = false;

export function checkFrontendAge({ force = false } = {}) {
    if (announced && !force) return null;
    const v = getComfyVersion();
    if (!parseVersion(v)) return null;
    announced = true;
    globalThis.__succyFrontendVersion = v;
    const newer = compareVersion(v, TESTED_FRONTEND) > 0;
    if (newer) {
        console.warn(`[Succy Pack] ComfyUI frontend ${v} is newer than the last one this pack was tested on (${TESTED_FRONTEND}). `
            + `If something looks off: run SuccyKill.on() and press F5 to switch the pack's UI layer off, then tell me which version you're on.`);
    }
    return { version: v, tested: TESTED_FRONTEND, newer };
}

if (!KILLED) {
    app.registerExtension({
        name: "Succy.FrontendAge",
        setup() { checkFrontendAge(); setTimeout(checkFrontendAge, 4000); },   // the version string can show up a beat after setup
    });
}
