// ============================================================
// lib/slots.js — wire reads that don't trip the frontend's "deprecated" alarm
// ------------------------------------------------------------
// Frontend 1.55 warns every time somebody peeks at `input.link` / `output.links` (it derives them from the link store on
// the fly). So we ask the store instead: node.getInputLink / isInputConnected, or a scan of graph.links for outputs.
// Old frontends without those methods fall back to the plain fields, shyly. Read-only: nothing here ever plugs a wire.
// v0.1.0 — 2026-10-16
// ============================================================

const linkMap = (g) => g?.links;
const getLink = (g, id) => (id == null ? null : (g?.getLink?.(id) ?? linkMap(g)?.get?.(id) ?? linkMap(g)?.[id] ?? null));

/** The link feeding input slot `i` (object), or null. */
export function inLink(node, i) {
    if (!node || i == null || i < 0) return null;
    if (typeof node.getInputLink === "function") { try { return node.getInputLink(i) ?? null; } catch (_) { /* fall through */ } }
    return getLink(node.graph, node.inputs?.[i]?.link);
}
/** Link id feeding input slot `i`, or null. */
export const inLinkId = (node, i) => inLink(node, i)?.id ?? null;
/** Is input slot `i` plugged? */
export function inWired(node, i) {
    if (!node || i == null || i < 0) return false;
    if (typeof node.isInputConnected === "function") { try { return !!node.isInputConnected(i); } catch (_) { /* fall through */ } }
    return node.inputs?.[i]?.link != null;
}
/** Same, by input name. */
export const inWiredByName = (node, name) => inWired(node, (node?.inputs || []).findIndex((x) => x?.name === name));
/** First input index that is plugged, or -1. */
export function firstWiredIn(node) {
    const n = node?.inputs?.length || 0;
    for (let i = 0; i < n; i++) if (inWired(node, i)) return i;
    return -1;
}
/** Link objects leaving output slot `o` (empty array when nothing hangs there). */
export function outLinks(node, o) {
    const g = node?.graph, m = linkMap(g), res = [];
    if (!g || !m) return res;
    const all = typeof m.values === "function" ? m.values() : Object.values(m);
    for (const l of all) if (l && String(l.origin_id) === String(node.id) && l.origin_slot === o) res.push(l);
    return res;
}
/** Link ids leaving output slot `o`. */
export const outLinkIds = (node, o) => outLinks(node, o).map((l) => l.id);
