const ANCHORS = [["top-left", "↖"], ["top", "↑"], ["top-right", "↗"], ["left", "←"], ["center", "•"], ["right", "→"], ["bottom-left", "↙"], ["bottom", "↓"], ["bottom-right", "↘"]];

