/* ---------- glue ---------- */
const nodeOf = (api) => api.liveNode?.() || api.node;
const wired = (api, name) => inWiredByName(nodeOf(api), name);
const isFolder = (api) => api.native.get("mode") === "folder" && !wired(api, "image");
const live = (api) => api.io.live_system?.() || {};
// the picture the box and the brush live on: the live `image` input, else this node's own (a loaded file, a Run)
const pic = (api) => {
    const l = live(api).image;
    if (l?.state === "live" && l.src) return { src: l.src, width: l.width, height: l.height };
    const s = api.io.shot_system?.() || {};
    return { src: s.src || "", width: s.width || 0, height: s.height || 0 };
};
// the view shows the output unless "Edit mask" is on (outView false); never set yet = the output
const viewsOut = (api) => { const v = api.state.get("outView"); return v === undefined || v === null ? true : !!v; };
const outOn = (api) => isFolder(api) || viewsOut(api);
const out = (api) => live(api).self?.image || {};
// the view: the result (Folder, or Result lit), else the picture to draw on
const view = (api) => { if (outOn(api)) { const o = out(api); return { src: o.src || "", width: o.width || 0, height: o.height || 0 }; } return pic(api); };
const sizeOf = (api, w, h) => {
    const g = (k) => api.native.get(k);
    const [sw, sh, cw, ch] = resizePlan(w, h, { resize: g("resize"), width: g("width"), height: g("height"), fit: g("fit"), anchor: g("anchor"),
        megapixels: g("megapixels"), scaleBy: g("scale_by"), multiple: g("multiple") });
    return { sw, sh, cw, ch };
};
// "1024×1024 · 1.05 MP": the same size + megapixels the Preview shows, so nobody needs a Preview just to read it (D-202)
const res = (w, h) => `${w}×${h} · ${(w * h / 1e6).toFixed(2)} MP`;
const say = (api) => {
    const o = out(api), info = o.info || {};
    if (isFolder(api)) {
        if (o.state === "wait") return "⚠ " + o.why;
        if (!info.filename) return "Reading the folder…";
        return `${info.index + 1}/${info.count} · ${info.filename} · out ${res(info.width, info.height)}${info.is_last ? " · last one" : ""}`;
    }
    const p = pic(api);
    if (!(p.width > 0 && p.height > 0)) return "";
    const ext = ["width_in", "height_in"].some((x) => wired(api, x)) && api.native.get("resize") === "custom";
    const { cw, ch } = sizeOf(api, p.width, p.height);
    const how = api.native.get("resize") === "custom" ? ` (${api.native.get("fit")})` : api.native.get("resize") === "scale" ? " (scale)" : "";
    return `Picture ${res(p.width, p.height)} · out ${ext ? "from the wire (known at Run)" : res(cw, ch)}${how}`;
};

