// ============================================================
// lib/sourcemap.js — "bundle line:col -> source file:line", read from js/succy-pack.js.map ON DEMAND
// ------------------------------------------------------------
// The pack ships as one bundle (D-139), so every stack frame says "succy-pack.js". Whoever must say WHERE
// (Governor errors, NodeStructure selfTest C7) asks here. The map is fetched only on that first question:
// a normal startup never downloads it. Without the bundle (sources served as-is) BUNDLE is "" and nothing loads.
//
//   SrcMap.load()               -> Promise (once; retried after a failure)
//   SrcMap.ready                -> true once decoded
//   SrcMap.frames(stack)        -> [{ url, file, line, col, fn }]  every http(s) .js frame, in order
//   SrcMap.locate(line, col)    -> { path, line, col } | null       bundle position (1-based, as stacks print it)
//   SrcMap.content(path)        -> source text | null               ("NodeStructure/core/define.js")
//
// She only opens the little black book when someone asks a name. Imports nothing.
// v0.1.0 — 2026-10-16
// ============================================================

const SELF = (() => { try { return new URL(import.meta.url); } catch (_) { return null; } })();
export const BUNDLE = SELF && /\/succy-pack\.js$/.test(SELF.pathname) ? "succy-pack.js" : "";

let MAP = null, pending = null;

const B64 = new Int8Array(128).fill(-1);
"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/".split("").forEach((c, i) => { B64[c.charCodeAt(0)] = i; });

// mappings -> per generated line: flat Int32Array [genCol, src, origLine, origCol, ...] (all 0-based)
function decode(json) {
    const s = String(json.mappings || ""), lines = [];
    let src = 0, ol = 0, oc = 0, i = 0, cur = [], gc = 0;
    const vlq = () => {
        let v = 0, shift = 0, d;
        do { d = B64[s.charCodeAt(i++)]; v += (d & 31) << shift; shift += 5; } while (d & 32);
        return v & 1 ? -(v >>> 1) : v >>> 1;
    };
    while (i <= s.length) {
        const ch = s[i];
        if (ch === ";" || i === s.length) { lines.push(Int32Array.from(cur)); cur = []; gc = 0; i++; continue; }
        if (ch === ",") { i++; continue; }
        gc += vlq();
        if (i < s.length && s[i] !== "," && s[i] !== ";") {
            src += vlq(); ol += vlq(); oc += vlq();
            if (i < s.length && s[i] !== "," && s[i] !== ";") vlq();       // name index: not needed
            cur.push(gc, src, ol, oc);
        }
    }
    return { sources: json.sources || [], content: json.sourcesContent || [], lines };
}

export const SrcMap = {
    bundle: BUNDLE,
    get ready() { return !!MAP; },

    load() {
        if (MAP) return Promise.resolve(MAP);
        if (!BUNDLE) return Promise.resolve(null);
        return (pending ||= fetch(new URL("./succy-pack.js.map", SELF), { cache: "no-cache" })
            .then((r) => (r.ok ? r.json() : Promise.reject(new Error("source map HTTP " + r.status))))
            .then((j) => (MAP = decode(j)))
            .catch((e) => { pending = null; throw e; }));
    },

    frames(stack) {
        const out = [];
        for (const raw of String(stack || "").split("\n")) {
            const l = raw.trim();
            const m = /(https?:\/\/[^\s()@]+?\.js)(?:\?[^:\s)]*)?:(\d+):(\d+)/.exec(l);
            if (!m) continue;
            const fn = /^at\s+(.+?)\s+\(/.exec(l)?.[1] || /^([^@\s]+)@/.exec(l)?.[1] || "";
            out.push({ url: m[1], file: m[1].split("/").pop(), line: +m[2], col: +m[3], fn });
        }
        return out;
    },

    locate(line, col) {
        const segs = MAP?.lines[line - 1];
        if (!segs || !segs.length) return null;
        const c = col - 1;
        let lo = 0, hi = segs.length / 4 - 1, k = -1;
        while (lo <= hi) { const mid = (lo + hi) >> 1; if (segs[mid * 4] <= c) { k = mid; lo = mid + 1; } else hi = mid - 1; }
        if (k < 0) k = 0;
        const path = MAP.sources[segs[k * 4 + 1]];
        return path ? { path, line: segs[k * 4 + 2] + 1, col: segs[k * 4 + 3] + 1 } : null;
    },

    content(path) {
        if (!MAP) return null;
        const i = MAP.sources.indexOf(path);
        return i >= 0 ? MAP.content[i] ?? null : null;
    },
};
