// ============================================================
// NodeStructure/util/mask-math.js — the Crop mask, computed in the BROWSER with the Python's own formulas (D-107)
// Pure functions on Float32Array [h*w] in 0..1: no DOM, no canvas, so Node can test them against Succy_Crop_Stitch.py.
//   rectMask   the rectangle (x, y, w, h in mask pixels; 0 = to the edge, like the native)
//   grow       square max-pool dilate (+) / min-pool erode (-): the same k = 2|px|+1 window as F.max_pool2d
//   blur       three box blurs with replicate padding (the Python `_blur`): a near-gaussian soft edge ~px wide
//   cropMask   the whole recipe: (box -> box feather) ∪ painted -> minus erased -> grow -> feather (D-112)
// Mirrors `Succy_Crop.crop` step by step: change one, change the other (and the test in dev/Theorycrafting).
// Succubus was here — same curves on both sides of the wire, darling. No surprises after the Run.
// ============================================================

import { quadMask, parseWarp } from "./blend-math.js";

const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);

export function rectMask(w, h, x, y, rw, rh) {
    const m = new Float32Array(w * h);
    const x0 = Math.min(Math.max(0, Math.round(x)), w - 1), y0 = Math.min(Math.max(0, Math.round(y)), h - 1);
    const x1 = rw > 0 ? Math.min(w, x0 + Math.round(rw)) : w, y1 = rh > 0 ? Math.min(h, y0 + Math.round(rh)) : h;
    for (let yy = y0; yy < y1; yy++) m.fill(1, yy * w + x0, yy * w + x1);
    return m;
}

// 1-D running max (or min) of radius r along rows or columns; samples outside the picture are ignored (padding = -inf).
// Monotonic deque: O(n) whatever the radius — a 1000 px grow costs the same as a 1 px one.
function pool1(src, w, h, r, horiz, useMax) {
    const out = new Float32Array(w * h);
    const n = horiz ? w : h, lines = horiz ? h : w, step = horiz ? 1 : w, lineStep = horiz ? w : 1;
    const q = new Int32Array(n);
    const better = useMax ? (a, b) => a >= b : (a, b) => a <= b;
    for (let l = 0; l < lines; l++) {
        const base = l * lineStep;
        let head = 0, tail = 0, next = 0;                    // q[head..tail) = indices, values monotonic
        for (let i = 0; i < n; i++) {
            const hi = Math.min(n - 1, i + r);
            for (; next <= hi; next++) {
                const v = src[base + next * step];
                while (tail > head && better(v, src[base + q[tail - 1] * step])) tail--;
                q[tail++] = next;
            }
            while (q[head] < i - r) head++;
            out[base + i * step] = src[base + q[head] * step];
        }
    }
    return out;
}

export function grow(m, w, h, px) {
    px = Math.round(px);
    if (!px) return m;
    const r = Math.abs(px), mx = px > 0;
    return pool1(pool1(m, w, h, r, true, mx), w, h, r, false, mx);
}

// 1-D box mean of radius r with replicate padding (sliding sum: cheap at any radius)
function box1(src, w, h, r, horiz) {
    const out = new Float32Array(w * h);
    const n = horiz ? w : h, lines = horiz ? h : w, step = horiz ? 1 : w, lineStep = horiz ? w : 1, k = 2 * r + 1;
    const at = (base, i) => src[base + (i < 0 ? 0 : i >= n ? n - 1 : i) * step];
    for (let l = 0; l < lines; l++) {
        const base = l * lineStep;
        let s = 0;
        for (let i = -r; i <= r; i++) s += at(base, i);
        for (let i = 0; i < n; i++) {
            out[base + i * step] = s / k;
            s += at(base, i + r + 1) - at(base, i - r);
        }
    }
    return out;
}

export function blur(m, w, h, px) {
    if (px <= 0) return m;
    const r = Math.max(1, Math.round(px / 3));
    let x = m;
    for (let i = 0; i < 3; i++) x = box1(box1(x, w, h, r, true), w, h, r, false);
    for (let i = 0; i < x.length; i++) x[i] = clamp01(x[i]);
    return x;
}

/**
 * The final Crop mask at w x h (any scale: `k` = mask pixels per ORIGINAL pixel, sizes in original pixels are scaled by it).
 * o = { base: Float32Array | null, box: {x,y,w,h} | null, boxFeather, add: Float32Array | null, erase: Float32Array | null, grow, feather, k }
 * base = the wired mask at w x h (D-164): it counts only if some pixel is over 0.5 (the Python's test), and every tool edits it.
 * box with w or h 0 = no rectangle drawn yet (D-164, was "to the edge"); box.quad = the dragged corners (JSON of 8 deltas, D-178).
 * Returns { mask, empty, bbox } — empty = nothing chosen: the Python then takes the whole picture. bbox = [x0, y0, x1, y1] in mask px of
 * the HARD selection (after grow, before feather: the Python pads it by the feather), null if the eraser left nothing (D-130).
 */
export function cropMask(w, h, o) {
    const k = o.k || 1;
    let sel = o.base && o.base.some((v) => v > 0.5) ? Float32Array.from(o.base) : null;
    if (o.box && o.box.w > 0 && o.box.h > 0) {
        // Free Edit Selection (D-178): the box's corners dragged = the Python's quad_mask (anti-aliased edge) instead of the rectangle
        const qd = parseWarp(o.box.quad);
        let r = qd ? quadMask(w, h, o.box, qd, k) : rectMask(w, h, o.box.x * k, o.box.y * k, o.box.w * k, o.box.h * k);
        if (o.boxFeather > 0) r = blur(r, w, h, o.boxFeather * k);
        if (!sel) sel = r; else for (let i = 0; i < sel.length; i++) if (r[i] > sel[i]) sel[i] = r[i];
    }
    if (o.add) {
        if (!sel) sel = Float32Array.from(o.add);
        else for (let i = 0; i < sel.length; i++) if (o.add[i] > sel[i]) sel[i] = o.add[i];
    }
    let any = false;
    if (sel) for (let i = 0; i < sel.length; i++) if (sel[i] > 0.01) { any = true; break; }
    if (!any) return { mask: new Float32Array(w * h).fill(1), empty: true };
    if (o.erase) for (let i = 0; i < sel.length; i++) sel[i] *= 1 - o.erase[i];
    sel = grow(sel, w, h, (o.grow || 0) * k);              // after the eraser: grow/shrink moves the erased edge too (D-112)
    let x0 = w, y0 = h, x1 = -1, y1 = -1;
    for (let yy = 0; yy < h; yy++) for (let xx = 0; xx < w; xx++) if (sel[yy * w + xx] > 0.01) {
        if (xx < x0) x0 = xx; if (xx > x1) x1 = xx; if (yy < y0) y0 = yy; if (yy > y1) y1 = yy;
    }
    const bbox = x1 < 0 ? null : [x0, y0, x1 + 1, y1 + 1];
    if (o.feather > 0) sel = blur(sel, w, h, o.feather * k);
    return { mask: sel, empty: false, bbox };
}

// Python's round(): halves go to the even neighbour (banker's), so the sizes below match the Python to the pixel
const pyRound = (v) => { const f = Math.floor(v), d = v - f; return d > 0.5 ? f + 1 : d < 0.5 ? f : (f % 2 === 0 ? f : f + 1); };

/** Python `_mp_size`: (w, h) scaled to `mp` megapixels, same aspect, never 0 px. */
export function mpSize(w, h, mp) {
    const s = Math.sqrt(mp * 1e6 / Math.max(1, w * h));
    return [Math.max(1, pyRound(w * s)), Math.max(1, pyRound(h * s))];
}

/** Python `_snap`: nearest multiple of m, never below m. */
export const snapTo = (v, m) => Math.max(m, pyRound(v / m) * m);

const ANCHORS = { "top-left": [0, 0], top: [0.5, 0], "top-right": [1, 0], left: [0, 0.5], center: [0.5, 0.5], right: [1, 0.5],
    "bottom-left": [0, 1], bottom: [0.5, 1], "bottom-right": [1, 1] };

/** Python `resize_plan` (Succy_Load.py, D-156): where a w x h picture goes -> [sw, sh, cw, ch, ox, oy]
 *  (resized to sw x sh, placed at ox, oy on a cw x ch canvas). Same arithmetic, same rounding. */
export function resizePlan(w, h, o = {}) {
    const m = Math.max(1, Math.trunc(Number(o.multiple) || 1));
    const sn = m > 1 ? (v) => snapTo(v, m) : (v) => Math.max(1, Math.trunc(v));
    const fit = o.fit || "fit";
    if (o.resize === "custom") {
        let W = Math.trunc(Number(o.width) || 0), H = Math.trunc(Number(o.height) || 0);
        if (W <= 0 && H <= 0) { W = w; H = h; }
        else if (W <= 0) W = Math.max(1, pyRound(w * H / h));
        else if (H <= 0) H = Math.max(1, pyRound(h * W / w));
        if (fit === "stretch") { const sw = sn(W), sh = sn(H); return [sw, sh, sw, sh, 0, 0]; }
        if (fit === "fit") { const s = Math.min(W / w, H / h), sw = sn(Math.max(1, pyRound(w * s))), sh = sn(Math.max(1, pyRound(h * s))); return [sw, sh, sw, sh, 0, 0]; }
        const cw = sn(W), ch = sn(H);
        let sw, sh;
        if (fit === "pad") { const s = Math.min(cw / w, ch / h); sw = Math.min(cw, Math.max(1, pyRound(w * s))); sh = Math.min(ch, Math.max(1, pyRound(h * s))); }
        else { const s = Math.max(cw / w, ch / h); sw = Math.max(cw, pyRound(w * s)); sh = Math.max(ch, pyRound(h * s)); }
        const [ax, ay] = ANCHORS[o.anchor] || [0.5, 0.5];
        return [sw, sh, cw, ch, pyRound((cw - sw) * ax), pyRound((ch - sh) * ay)];
    }
    if (o.resize === "scale") {
        const mp = Number(o.megapixels) || 0, k = Number(o.scaleBy ?? 1) || 1;
        const [bw, bh] = mp > 0 ? mpSize(w, h, mp) : [w, h];
        const sw = sn(Math.max(1, pyRound(bw * k))), sh = sn(Math.max(1, pyRound(bh * k)));
        return [sw, sh, sw, sh, 0, 0];
    }
    const sw = sn(w), sh = sn(h);
    return [sw, sh, sw, sh, 0, 0];
}
