// ============================================================
// NodeStructure/components/strip.js — a STRIP of thumbnails of a folder (Load & Resize, D-156)
//   strip_element   one row of little pictures that scrolls sideways (wheel = sideways, the canvas doesn't zoom): the folder's
//                   pictures, the one the node is on lit, the one that comes next marked. A click picks one: it either writes the
//                   bound value (an index) or, with `seekOn`, asks the node's route to go on from there. The node's Python lists the
//                   folder (`list` route) and serves the thumbnails (`thumb` route, cached there); this piece only shows and asks
//                   again when the folder, `refresh` or the node changes.
// The node only names its routes and refs. Succubus was here — flip through them, darling, she won't tell which one you lingered on.
// ============================================================
import { mkEl } from "./index.js";
import { piece } from "../catalog/registry.js";
import { C, ex, N, R, S } from "../catalog/kit.js";

const STRIPS = new Set();
// the last listing of every (graph, node, folder): a node rebuilt by Ctrl+Z puts its thumbnails up in the same frame instead of
// "Reading the folder…" and a row of empty cells (the pictures come back from the browser cache); the real listing follows
const LASTLIST = new Map();
const SSTATS = { lists: 0, failed: 0, last: "" };
export const stripStats = () => ({ strips: STRIPS.size, ...SSTATS });

const CSS = `
.ns-strip{display:flex;flex-direction:column;gap:3px;min-width:0}
.ns-strip-wrap{display:flex;align-items:stretch;gap:3px;min-width:0}
.ns-strip-wrap .ns-strip-row{flex:1 1 auto;min-width:0}
.ns-strip-arrow{flex:0 0 18px;border:1px solid var(--ns-c-border,#444);border-radius:4px;background:var(--ns-bg-2,#1a1a1a);color:var(--ns-c-text,#ddd);font:12px monospace;padding:0;cursor:pointer;margin-bottom:6px}
.ns-strip-arrow:hover:not(:disabled){border-color:var(--ns-t-info,#4aa3ff);color:var(--ns-t-info,#4aa3ff)}
.ns-strip-arrow:disabled{opacity:.3;cursor:default}
.ns-strip-wrap[hidden]{display:none}
.ns-strip-row{display:flex;gap:4px;overflow-x:auto;overflow-y:hidden;padding:2px 2px 6px;scrollbar-width:thin;min-height:calc(var(--ns-strip-s,64px) + 8px)}
.ns-strip-cell{position:relative;flex:0 0 auto;width:var(--ns-strip-s,64px);height:var(--ns-strip-s,64px);border-radius:5px;overflow:hidden;cursor:pointer;
  background:#0b0b0d;border:2px solid transparent;transition:border-color .12s,transform .12s;box-sizing:border-box}
.ns-strip-cell:hover{border-color:color-mix(in srgb,var(--ns-t-info,#4aa3ff) 70%,transparent);transform:translateY(-1px)}
.ns-strip-cell img{width:100%;height:100%;object-fit:cover;display:block;pointer-events:none}
.ns-strip-cell.on{border-color:var(--ns-t-warn,#e0a040);box-shadow:0 0 8px color-mix(in srgb,var(--ns-t-warn,#e0a040) 60%,transparent)}
.ns-strip-cell.nx::after{content:"▶";position:absolute;right:2px;top:1px;font:bold 10px monospace;color:var(--ns-t-ok,#5fd38d);text-shadow:0 1px 2px #000}
.ns-strip-cell i{position:absolute;left:0;right:0;bottom:0;padding:1px 3px;font:9px/1.3 monospace;font-style:normal;color:#fff;background:rgba(0,0,0,.6);
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ns-strip-head{display:flex;align-items:center;gap:6px}
.ns-strip-head[hidden]{display:none}
.ns-strip-top{border:1px solid var(--ns-c-border,#444);border-radius:4px;background:var(--ns-bg-2,#1a1a1a);color:var(--ns-c-text,#ddd);font:11px monospace;padding:1px 7px;cursor:pointer}
.ns-strip-top:hover{border-color:var(--ns-t-ok,#5fd38d);color:var(--ns-t-ok,#5fd38d)}
.ns-strip-msg{font:10px monospace;color:var(--ns-c-text-3,#aaa);padding:2px}
.ns-strip-msg[hidden]{display:none}
`;

piece(C("strip_element", {
    scopo: "Sideways strip of a folder's thumbnails (listed and served by the node's routes): current one lit, next one marked, click to pick.",
    natura: "works", dominio: "ui", estado: "draft", archetipo: "trigger",
    tag: ["image", "folder", "preview", "choice"], css: CSS,
    props: {
        folder: R("the folder as written on the node (ref, e.g. $native.folder)"),
        list: S("POST route {node_id, folder} -> {files, count, next, last} or {error}"),
        thumb: S("GET route of one thumbnail: {folder} {file} {s} are filled in"),
        seek: S("POST route {node_id, folder, pos}: used instead of the bound value when `seekOn` is true"),
        seekOn: R("true = a click asks `seek` (go on from there); false = a click writes the bound value (ref)"),
        current: R("index to light instead of the one the route says (ref, e.g. $native.index in index mode)"),
        refresh: R("any value: when it changes the folder is listed again (ref, e.g. the node's last Run)"),
        report: S("cache key where one line is written: how many pictures, which one"),
        size: N("thumbnail side in px", 64),
    },
    esempio: ex({ t: "strip_element", folder: "", list: "", thumb: "" }),
}), (node, h) => {
    const el = mkEl("div", "ns-strip"), row = mkEl("div", "ns-strip-row"), msg = mkEl("div", "ns-strip-msg");
    // ↺ (only with `seekOn`): Next starts again from the first picture
    const head = mkEl("div", "ns-strip-head"), top = mkEl("button", "ns-strip-top");
    top.textContent = "↺ from the top"; top.title = "Next starts again from the first picture";
    head.append(top);
    // ◀ ▶: a long folder does not fit — these walk the row a page at a time (the wheel does too)
    const wrapRow = mkEl("div", "ns-strip-wrap"), left = mkEl("button", "ns-strip-arrow"), right = mkEl("button", "ns-strip-arrow");
    left.textContent = "◀"; right.textContent = "▶"; left.title = "Scroll the pictures left"; right.title = "Scroll the pictures right";
    wrapRow.append(left, row, right);
    el.append(head, wrapRow, msg);
    el.style.setProperty("--ns-strip-s", Math.max(32, Math.min(160, Number(node.size) || 64)) + "px");
    const me = { files: [], next: 0, last: null, key: "", token: 0, cur: -1, onCommit: null, pick: 0 };
    STRIPS.add(me);
    h.bag.add(() => { STRIPS.delete(me); me.token++; });
    const A = () => globalThis.app?.api;
    const nodeId = () => (h.rt.api.liveNode?.() || h.rt.node)?.id;
    const folder = () => String(h.val(node.folder) ?? "");
    const lkey = () => { const n = h.rt.node; return `${n?.graph?.id ?? "g"}:${n?.id ?? "?"}:${folder()}`; };
    const said = { text: null };
    const say = (text) => { if (!node.report || said.text === text) return; said.text = text; h.rt.api.cache.set(node.report, text); h.rt.api.refresh(); };
    // sideways wheel: the strip scrolls, the canvas under it stays put
    h.listen(row, "wheel", (e) => { if (row.scrollWidth <= row.clientWidth) return; e.preventDefault(); e.stopPropagation(); row.scrollLeft += (Math.abs(e.deltaY) > Math.abs(e.deltaX) ? e.deltaY : e.deltaX); }, { passive: false });
    h.listen(row, "pointerdown", (e) => e.stopPropagation());
    h.listen(top, "pointerdown", (e) => e.stopPropagation());
    for (const [b, dir] of [[left, -1], [right, 1]]) {
        h.listen(b, "pointerdown", (e) => e.stopPropagation());
        h.listen(b, "click", (e) => { e.stopPropagation(); row.scrollBy({ left: dir * Math.max(80, row.clientWidth * 0.8), behavior: "smooth" }); });
    }
    const arrows = () => { left.disabled = row.scrollLeft <= 1; right.disabled = row.scrollLeft + row.clientWidth >= row.scrollWidth - 1; };
    h.listen(row, "scroll", arrows);
    h.listen(top, "click", (e) => { e.stopPropagation(); if (me.files.length) pick(0); });

    const curOf = () => {
        const c = h.val(node.current);
        if (c !== undefined && c !== null && c !== "" && Number.isFinite(Number(c))) return Math.max(0, Math.min(me.files.length - 1, Number(c)));
        return me.last ?? me.next ?? 0;
    };
    const paint = () => {
        const cur = me.files.length ? curOf() : -1, seekOn = !!h.val(node.seekOn);
        head.hidden = !seekOn || !me.files.length;
        arrows(); setTimeout(arrows, 120);
        [...row.children].forEach((c, i) => { c.classList.toggle("on", i === cur); c.classList.toggle("nx", seekOn && me.last != null && i === me.next && i !== cur); });
        if (cur !== me.cur && cur >= 0) { me.cur = cur; row.children[cur]?.scrollIntoView?.({ block: "nearest", inline: "nearest" }); }
        say(me.files.length ? `${me.files.length} pictures · ${cur + 1}/${me.files.length} ${me.files[cur] || ""}${seekOn && me.last != null ? ` · next ${me.files[me.next] || ""}` : ""}` : msg.textContent);
    };
    const build = () => {
        row.replaceChildren();
        const f = folder(), s = Math.max(64, (Number(node.size) || 64) * 2);
        me.files.forEach((name, i) => {
            const c = mkEl("div", "ns-strip-cell"), img = mkEl("img"), cap = mkEl("i");
            img.loading = "lazy"; img.decoding = "async"; img.alt = name;
            img.src = A()?.apiURL?.(String(node.thumb || "").replace("{folder}", encodeURIComponent(f)).replace("{file}", encodeURIComponent(name)).replace("{s}", String(s))) || "";
            cap.textContent = name; c.title = `${i}: ${name}`;
            c.append(img, cap);
            h.listen(c, "click", (e) => { e.stopPropagation(); pick(i); });
            row.appendChild(c);
        });
        me.cur = -1; paint();
    };
    const pick = async (i) => {
        if (h.val(node.seekOn) && node.seek) {
            try {
                await A().fetchApi(node.seek, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ node_id: nodeId(), folder: folder(), pos: i }) });
                me.next = i; me.last = null; me.key = ""; update();
            } catch (e) { SSTATS.failed++; SSTATS.last = String(e?.message || e); }
            return;
        }
        me.pick = i; paint(); me.onCommit?.();
    };
    const load = async (key) => {
        const t = ++me.token;
        if (!me.files.length) { msg.hidden = false; msg.textContent = "Reading the folder…"; }
        try {
            SSTATS.lists++;
            const r = await A().fetchApi(node.list, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ node_id: nodeId(), folder: folder() }) });
            const j = await r.json();
            if (t !== me.token) return;
            if (j.error) { me.files = []; build(); msg.textContent = "⚠ " + j.error; say(msg.textContent); return; }
            const files = Array.isArray(j.files) ? j.files.map(String) : [];
            const same = files.length === me.files.length && files.every((x, i) => x === me.files[i]);
            me.files = files; me.next = Number(j.next) || 0; me.last = j.last == null ? null : Number(j.last);
            LASTLIST.delete(lkey()); LASTLIST.set(lkey(), { files, next: me.next, last: me.last }); while (LASTLIST.size > 8) LASTLIST.delete(LASTLIST.keys().next().value);
            msg.hidden = files.length > 0; msg.textContent = files.length ? "" : "No pictures in this folder";
            if (same) paint(); else build();
        } catch (e) {
            if (t !== me.token) return;
            SSTATS.failed++; SSTATS.last = String(e?.message || e);
            msg.hidden = false; msg.textContent = "⚠ the folder can't be read"; say(msg.textContent);
        }
    };
    const update = () => {
        if (!node.list || !A()) return;
        const key = `${nodeId()}|${folder()}|${h.val(node.refresh) ?? ""}`;
        if (key !== me.key) {
            if (!me.key && !me.files.length) {           // freshly built (undo): the last listing of this node, now
                const hit = LASTLIST.get(lkey());
                if (hit) { me.files = hit.files; me.next = hit.next; me.last = hit.last; msg.hidden = true; build(); }
            }
            me.key = key; load(key);
        } else paint();
    };
    queueMicrotask(update);
    return { el, update, handlesText: true, value: { get: () => me.pick, set: () => paint(), events: [], onCommit: (fn) => { me.onCommit = fn; } } };
});
